export type TroisJour = [number, number, number, number, number, number, string, string, string];
export const TOTAL_PREVU = 365;
/** Les grandes parties : [premier jour, titre] */
export const TROIS_BLOCS: Array<[number, string]> = [[1,"La promesse et la venue"],[13,"Préparer le chemin"],[18,"Suivre Jésus"],[26,"Le Royaume : le sermon sur la montagne"],[38,"Les paraboles du Royaume"],[58,"Signes et compassion"],[80,"Qui est Jésus ?"],[95,"Vers Jérusalem"],[107,"La dernière nuit"],[121,"La croix"],[131,"Il est vivant"],[141,"L'Esprit et l'Église naissante"],[158,"Jusqu'aux extrémités de la terre"],[178,"Le salut par grâce"],[205,"Vivre en Christ"],[232,"L'Église, un seul corps"],[266,"Serviteurs fidèles"],[282,"Jésus, plus grand que tout"],[300,"Une foi qui tient bon"],[316,"Marcher dans l'amour et la vérité"],[326,"Veiller dans l'espérance"],[337,"Toutes choses nouvelles"]];
export const TROIS: TroisJour[] = [[1,1,19,33,43,1,"Au commencement était la Parole","Jean : la Parole était Dieu, et tout a été fait par elle ; par la parole de l'Éternel les cieux ont été faits ; Dieu dit, et la lumière fut.","Qu'est-ce que ça change de savoir que la Parole qui a créé le monde s'est faite homme ?"],
[10,7,19,2,58,1,"Le Fils, héritier de tout","Hébreux : Dieu nous a parlé par le Fils, plus grand que les anges ; tu es mon Fils, je t'ai engendré aujourd'hui ; Dieu promet à David : je serai pour lui un père.","Est-ce que j'écoute vraiment ce que Dieu dit par son Fils ?"],
[1,2,20,8,51,1,"Le premier-né de toute la création","Paul : tout a été créé par lui et pour lui, et tout tient en lui ; la Sagesse était à l'œuvre auprès de Dieu à la création ; Dieu forme l'homme et souffle en lui la vie.","Qu'est-ce qui, dans ma vie, ne « tient » pas encore en Christ ?"],
[8,4,19,132,40,1,"Fils de David, fils d'Abraham","Matthieu ouvre avec une généalogie pleine de grâces inattendues : Tamar, Rahab, Ruth ; Dieu a juré à David un descendant sur son trône ; Boaz rachète Ruth, et de là naîtra David.","Est-ce que je crois que Dieu peut écrire une histoire de grâce avec la mienne ?"],
[9,1,19,113,42,1,"Rien n'est impossible à Dieu","L'ange annonce à Marie la naissance de Jésus, et elle répond : je suis la servante du Seigneur ; il donne une maison à la femme stérile ; Anne, stérile, prie et reçoit Samuel.","À quelle parole de Dieu ai-je besoin de répondre : qu'il me soit fait selon ta parole ?"],
[9,2,19,98,42,1,"Le chant de Marie","Marie chante le Dieu qui élève les humbles, et Zacharie bénit celui qui visite son peuple ; chantez un cantique nouveau, il s'est souvenu de sa bonté ; le cantique d'Anne chantait déjà ce renversement.","Pour quelle grâce puis-je écrire mon propre chant de louange ?"],
[33,5,19,96,42,2,"Une grande joie pour tout le peuple","Jésus naît à Bethléem et les anges l'annoncent aux bergers ; annoncez de jour en jour son salut ; Michée : de toi, Bethléem, sortira celui qui dominera sur Israël.","Comment accueillir la grande joie de Noël au milieu de ma vie ordinaire ?"],
[23,49,19,131,42,2,"Mes yeux ont vu ton salut","Siméon prend l'enfant dans ses bras : mes yeux ont vu ton salut, la lumière des nations ; mon âme est en moi comme un enfant apaisé ; Ésaïe : je t'établis pour être la lumière des nations.","Est-ce que j'attends le Seigneur avec la patience de Siméon ?"],
[4,24,19,72,40,2,"L'étoile et les mages","Des mages venus d'Orient suivent l'étoile et offrent leurs présents, pendant qu'Hérode veut tuer l'enfant ; les rois apporteront des présents ; Balaam voyait une étoile sortir de Jacob.","Qu'est-ce que je viens offrir au roi aujourd'hui ?"],
[23,9,19,89,48,4,"Quand les temps furent accomplis","Paul : Dieu a envoyé son Fils, né d'une femme, pour faire de nous ses enfants ; il m'appellera : tu es mon Père ; Ésaïe : un enfant nous est né, un fils nous est donné.","Est-ce que je vis comme un enfant de Dieu ou comme un serviteur qui a peur ?"],
[23,45,19,138,50,2,"Il s'est abaissé","Paul : lui qui était Dieu s'est fait serviteur, et tout genou fléchira devant lui ; l'Éternel est élevé, mais il voit les humbles ; Ésaïe : devant moi, tout genou fléchira.","Où Jésus m'invite-t-il à m'abaisser comme lui ?"],
[2,33,19,36,62,1,"Ce que nous avons vu et touché","Jean : nous avons vu et touché la Parole de vie, et Dieu est lumière ; dans ta lumière nous voyons la lumière ; Moïse demande : fais-moi voir ta gloire.","Comment ma communion avec Dieu se voit-elle dans ma joie ?"],
[39,3,19,51,40,3,"Le baptême de Jésus","Jean appelle à changer de vie, et Jésus est baptisé : celui-ci est mon Fils bien-aimé ; lave-moi, et je serai purifié ; Malachie annonçait le messager qui prépare le chemin.","Qu'est-ce que je dois changer pour préparer le chemin du Seigneur ?"],
[23,40,19,85,42,3,"Une voix dans le désert","Jean dit à chacun comment changer : partagez, soyez honnêtes, ne profitez de personne ; la justice marchera devant lui ; Ésaïe : préparez dans le désert le chemin de l'Éternel.","Dans mon travail, qu'est-ce que la conversion changerait concrètement ?"],
[12,5,19,5,41,1,"Le commencement de l'Évangile","Marc va vite : baptême, appel des pêcheurs, guérisons, et Jésus qui prie seul avant l'aube ; dès le matin, je me tourne vers toi ; un lépreux est purifié, comme Naaman autrefois.","Quel moment de prière seul à seul je garde avec Dieu ?"],
[5,8,19,91,40,4,"La tentation au désert","Jésus est tenté et répond par l'Écriture : l'homme ne vivra pas de pain seulement ; le tentateur cite le psaume 91 en le tordant ; Moïse avait appris à Israël à vivre de toute parole de Dieu.","Quelle parole de l'Écriture ai-je pour répondre à ma tentation ?"],
[23,61,19,146,42,4,"L'Esprit du Seigneur est sur moi","À Nazareth, Jésus lit Ésaïe et déclare : aujourd'hui cette parole est accomplie ; l'Éternel délivre les captifs et ouvre les yeux des aveugles ; Ésaïe : il m'a envoyé porter la bonne nouvelle aux malheureux.","De quoi ai-je besoin que Jésus me libère ?"],
[1,28,19,34,43,1,"Venez et voyez","André amène Pierre, Philippe dit à Nathanaël : viens et vois, et Jésus annonce le ciel ouvert ; goûtez et voyez que l'Éternel est bon ; Jacob voyait l'échelle entre ciel et terre.","À qui pourrais-je dire « viens et vois » ?"],
[11,19,19,107,42,5,"Pêcheurs d'hommes","Après une pêche miraculeuse, Pierre dit : éloigne-toi de moi, je suis un pécheur ; et Jésus : désormais, tu seras pêcheur d'hommes ; ils ont vu les œuvres de Dieu sur les grandes eaux ; Élisée laisse ses bœufs pour suivre Élie.","Qu'est-ce que je laisse pour suivre Jésus ?"],
[28,6,19,32,41,2,"Venu pour les pécheurs","Jésus pardonne au paralysé, appelle Lévi et mange avec les pécheurs ; heureux celui dont la faute est pardonnée ; Osée : j'aime la bonté plus que les sacrifices.","Avec qui Jésus m'invite-t-il à partager la table ?"],
[26,34,19,103,40,9,"Comme des brebis sans berger","Jésus appelle Matthieu, guérit, et voit les foules sans berger : la moisson est grande ; il pardonne tes fautes, il guérit tes maladies ; Ézéchiel : je chercherai moi-même mes brebis.","Pour quelle « moisson » vais-je prier ?"],
[4,11,19,133,41,3,"Les Douze et la nouvelle famille","Jésus appelle les Douze pour être avec lui, et dit : celui qui fait la volonté de Dieu est mon frère, ma sœur, ma mère ; qu'il est doux pour des frères de vivre unis ; Dieu partage l'Esprit de Moïse avec soixante-dix anciens.","Qui fait partie de ma famille dans la foi ?"],
[24,1,19,121,40,10,"Envoyés comme des brebis","Jésus envoie les Douze : n'ayez pas peur, vous valez plus que beaucoup de moineaux ; l'Éternel te gardera ; Jérémie est envoyé malgré sa peur : je suis avec toi.","Où Jésus m'envoie-t-il, malgré ma peur ?"],
[12,2,19,16,42,9,"Prendre sa croix","Jésus envoie les Douze, nourrit la foule, puis dit : si quelqu'un veut me suivre, qu'il renonce à lui-même ; tu me fais connaître le chemin de la vie ; Élisée refuse de quitter Élie : je ne te quitterai pas.","Que voudrait dire « renoncer à moi-même » aujourd'hui ?"],
[6,24,20,24,42,14,"Le prix à payer","Jésus parle de la tour qu'on calcule avant de bâtir : celui qui ne renonce pas à tout ne peut être mon disciple ; prépare ton ouvrage avant de bâtir ta maison ; Josué : choisissez aujourd'hui qui vous voulez servir.","Ai-je mesuré ce que suivre Jésus me coûte, et ce que cela vaut ?"],
[2,19,19,1,40,5,"Heureux…","Sur la montagne, Jésus proclame les béatitudes : heureux les pauvres en esprit, ceux qui pleurent, les doux ; heureux l'homme qui ne suit pas le conseil des méchants ; au Sinaï, Dieu donnait sa loi sur la montagne.","Quelle béatitude me parle le plus aujourd'hui ?"],
[2,20,19,119,40,5,"Sel et lumière","Vous êtes le sel de la terre et la lumière du monde ; je ne suis pas venu abolir la loi, mais l'accomplir ; ta parole est une lampe à mes pieds ; les dix paroles données au Sinaï.","Où puis-je être sel et lumière cette semaine ?"],
[3,19,20,25,40,5,"Aimez vos ennemis","Jésus va jusqu'au cœur : ne pas se mettre en colère, ne pas convoiter, aimer ses ennemis ; si ton ennemi a faim, donne-lui à manger ; la loi disait déjà : aime ton prochain comme toi-même.","Pour quel « ennemi » puis-je prier aujourd'hui ?"],
[11,8,19,145,40,6,"Notre Père","Jésus apprend à prier dans le secret : Notre Père qui es aux cieux ; l'Éternel est près de tous ceux qui l'invoquent ; Salomon priait : écoute du haut des cieux.","Quelle phrase du Notre Père vais-je prier lentement aujourd'hui ?"],
[11,17,19,23,40,6,"Ne vous inquiétez pas","Regardez les oiseaux du ciel, cherchez d'abord le royaume, et tout le reste vous sera donné ; je ne manquerai de rien ; Élie est nourri par les corbeaux.","Quelle inquiétude vais-je remettre au Père aujourd'hui ?"],
[24,17,19,15,40,7,"Bâtir sur le roc","Ne jugez pas, demandez et vous recevrez, bâtissez sur le roc ; qui séjournera dans ta tente ? ; Jérémie : béni l'homme qui se confie en l'Éternel, il est comme un arbre près des eaux.","Sur quoi est-ce que je bâtis ma vie ?"],
[5,30,20,14,40,7,"La porte étroite","Deux portes, deux arbres, deux maisons : Jésus met devant un choix ; telle voie paraît droite à l'homme, mais elle mène à la mort ; Moïse : j'ai mis devant toi la vie et la mort, choisis la vie.","Quel choix de vie dois-je faire aujourd'hui ?"],
[12,6,19,112,42,6,"Faites du bien à ceux qui vous haïssent","Soyez miséricordieux comme votre Père, donnez et l'on vous donnera ; l'homme juste donne largement ; Élisée fait nourrir l'armée ennemie au lieu de la frapper.","Envers qui puis-je être miséricordieux comme le Père ?"],
[9,16,20,4,42,6,"Le cœur et les fruits","Un bon arbre porte de bons fruits, et la bouche parle de ce qui remplit le cœur ; garde ton cœur plus que tout ; Dieu regarde au cœur quand il choisit David.","Qu'est-ce qui remplit mon cœur en ce moment ?"],
[1,18,19,141,42,11,"Apprends-nous à prier","Les disciples demandent à apprendre à prier, et Jésus parle de l'ami qui insiste et du Père qui donne l'Esprit ; que ma prière monte comme l'encens ; Abraham intercède avec audace pour Sodome.","Pour quoi vais-je persévérer dans la prière ?"],
[6,7,21,5,42,12,"Gardez-vous de la cupidité","Jésus raconte le riche qui agrandit ses greniers et meurt la nuit même ; celui qui aime l'argent n'en est jamais rassasié ; Acan convoite le butin et le cache.","Où la cupidité se cache-t-elle chez moi ?"],
[2,12,19,130,42,12,"Soyez prêts","Que vos lampes soient allumées : heureux le serviteur que le maître trouvera en train de veiller ; mon âme attend le Seigneur plus que les gardes n'attendent le matin ; Israël mangeait la Pâque prêt à partir.","Si le Seigneur venait ce soir, me trouverait-il en train de veiller ?"],
[23,55,19,126,40,13,"Le semeur","La semence tombe sur le chemin, sur la pierre, dans les épines, dans la bonne terre ; ceux qui sèment avec larmes moissonnent avec joie ; Ésaïe : ma parole ne revient pas à moi sans effet.","Quel terrain est mon cœur aujourd'hui ?"],
[26,17,19,92,40,13,"La graine et le levain","Le Royaume commence petit comme une graine de moutarde et agit comme le levain ; le juste pousse comme le cèdre du Liban ; Ézéchiel : un tendre rameau deviendra un cèdre où nicheront les oiseaux.","Quel petit commencement Dieu fait-il grandir chez moi ?"],
[27,12,20,2,40,13,"Le trésor et la perle","Un homme vend tout pour un trésor caché, un marchand pour une perle, puis le filet trie les poissons à la fin ; cherche la sagesse comme un trésor ; Daniel : les sages brilleront comme la splendeur du ciel.","Qu'est-ce que je serais prêt à laisser pour le Royaume ?"],
[32,1,19,65,41,4,"Même le vent lui obéit","Après les paraboles, Jésus dort dans la barque puis apaise la tempête : pourquoi avez-vous peur ? ; Dieu apaise le grondement des mers ; Jonas dormait dans le bateau pendant la tempête.","Quelle tempête ai-je besoin de confier à Jésus ?"],
[12,4,19,30,42,8,"Ne crains pas, crois seulement","Une femme malade touche son vêtement, et la fille de Jaïre revient à la vie ; tu m'as fait remonter du séjour des morts ; Élisée rend la vie au fils de la Sunamite.","Où ai-je besoin d'entendre « ne crains pas, crois seulement » ?"],
[14,28,19,41,42,10,"Qui est mon prochain ?","Jésus raconte le Samaritain qui s'arrête pour soigner un blessé ; heureux celui qui prend soin du faible ; des Samaritains avaient autrefois soigné des captifs sur la route de Jéricho.","Pour qui dois-je m'arrêter ?"],
[5,6,19,27,42,10,"Une seule chose est nécessaire","Marie s'assoit aux pieds de Jésus pendant que Marthe s'agite ; je demande une seule chose : habiter dans la maison de l'Éternel ; Écoute, Israël : tu aimeras l'Éternel de tout ton cœur.","Ai-je pris le temps de m'asseoir aux pieds de Jésus aujourd'hui ?"],
[33,7,19,100,42,15,"La brebis et la pièce perdues","Le berger cherche sa brebis et la femme sa pièce : il y a de la joie au ciel pour un pécheur qui revient ; nous sommes son peuple, le troupeau qu'il fait paître ; Michée : quel Dieu est comme toi, qui pardonnes ?","Est-ce que je mesure la joie de Dieu quand quelqu'un revient ?"],
[28,11,19,86,42,15,"Le père qui court","Le fils perdu revient, le père court vers lui, et le fils aîné refuse d'entrer ; tu es bon, Seigneur, prompt à pardonner ; Osée : je le tirais avec des liens d'amour, mon cœur s'émeut.","Suis-je plutôt le fils qui revient, ou le fils aîné ?"],
[13,29,20,3,42,16,"Fidèle dans les petites choses","Celui qui est fidèle dans les petites choses l'est aussi dans les grandes, et nul ne peut servir Dieu et l'argent ; honore l'Éternel avec tes biens ; David : tout vient de toi, nous te donnons ce que nous avons reçu.","Est-ce que je gère mon argent comme quelqu'un qui appartient à Dieu ?"],
[30,6,19,49,42,16,"Le riche et Lazare","Le riche festoie sans voir Lazare couché à sa porte ; l'homme dans sa gloire ne dure pas ; Amos : malheur à ceux qui sont tranquilles sur leurs lits d'ivoire.","Quel Lazare est à ma porte ?"],
[35,1,19,88,42,18,"Prier sans se décourager","La veuve insiste devant le juge, et le publicain repart justifié plutôt que le pharisien ; je crie jour et nuit devant toi ; Habacuc : jusqu'à quand crierai-je ?","Pour quelle prière ai-je failli abandonner ?"],
[11,3,19,8,42,18,"Comme un enfant","Laissez venir à moi les petits enfants, dit Jésus, puis le jeune homme riche s'en va triste ; par la bouche des enfants, tu as fondé ta louange ; Salomon se dit « un petit enfant » devant Dieu et demande la sagesse.","Qu'est-ce qui m'empêche de recevoir le Royaume comme un enfant ?"],
[2,22,19,24,42,19,"Zachée descend","Zachée monte dans un arbre pour voir Jésus, qui s'invite chez lui, et il rend quatre fois ce qu'il a pris ; qui montera à la montagne de l'Éternel ? ; la loi demandait de rendre quatre fois ce qu'on avait volé.","Qu'est-ce que la rencontre avec Jésus doit changer dans mes comptes ?"],
[1,50,19,25,40,18,"Soixante-dix fois sept fois","Le serviteur pardonné d'une dette immense refuse de pardonner une petite dette ; à cause de ton nom, pardonne ma faute, car elle est grande ; Joseph pardonne à ses frères : Dieu l'a changé en bien.","Qui ai-je encore besoin de pardonner ?"],
[32,4,19,75,40,20,"Les derniers seront les premiers","Les ouvriers de la dernière heure reçoivent le même salaire, et ceux du matin murmurent ; c'est Dieu qui abaisse l'un et élève l'autre ; Jonas est fâché que Dieu fasse grâce à Ninive.","Est-ce que la générosité de Dieu envers d'autres me dérange ?"],
[38,9,19,118,40,21,"Le roi entre sur un ânon","Jésus entre à Jérusalem, humble, sur un ânon, et la foule crie hosanna, puis il raconte les vignerons ; béni soit celui qui vient au nom de l'Éternel ; Zacharie : voici ton roi qui vient à toi, humble.","Comment j'accueille Jésus quand il entre dans ma vie ?"],
[23,25,19,45,40,22,"Les noces du fils du roi","Le roi invite au festin de noces, beaucoup s'excusent et d'autres sont appelés des carrefours ; le chant des noces du roi ; Ésaïe : l'Éternel prépare un festin pour tous les peuples.","Est-ce que je réponds à l'invitation de Dieu, ou est-ce que je m'excuse ?"],
[1,41,22,3,40,25,"Les lampes et les talents","Cinq jeunes filles ont gardé de l'huile pour l'arrivée de l'époux, et les serviteurs font fructifier les talents confiés ; la bien-aimée cherche celui que son cœur aime ; Joseph prépare des réserves avant la famine.","Qu'est-ce que je fais des talents que Dieu m'a confiés ?"],
[23,58,20,19,40,25,"C'est à moi que vous l'avez fait","Le roi sépare les brebis et les boucs : j'avais faim, et vous m'avez donné à manger ; celui qui a pitié du pauvre prête à l'Éternel ; Ésaïe : partage ton pain avec celui qui a faim.","Où ai-je rencontré Jésus dans le plus petit cette semaine ?"],
[23,62,22,2,43,2,"Le vin des noces","À Cana, Jésus change l'eau en vin, le premier de ses signes ; le Cantique chante la saison des chants et de la joie ; Ésaïe : comme l'époux se réjouit de l'épouse, ton Dieu se réjouira de toi.","Dans quel manque ai-je besoin que Jésus apporte sa joie ?"],
[23,65,19,68,41,5,"Libéré et envoyé","Un homme tourmenté vit dans les tombeaux ; Jésus le libère et l'envoie raconter ce que Dieu a fait ; Dieu fait sortir les captifs ; Ésaïe décrivait un peuple qui habite les tombeaux.","À qui puis-je raconter ce que Dieu a fait pour moi ?"],
[3,15,19,6,41,5,"Douze ans d'attente","Une femme malade depuis douze ans touche son vêtement, et Jésus l'appelle « ma fille » ; guéris-moi, Éternel, mes os tremblent ; la loi la laissait impure et seule.","Quelle honte ai-je besoin d'apporter à Jésus ?"],
[3,13,19,147,40,8,"Il a pris nos infirmités","Jésus touche un lépreux, guérit le serviteur d'un centurion et calme la mer ; il guérit ceux qui ont le cœur brisé ; la loi mettait le lépreux à l'écart du camp.","Qui, autour de moi, attend d'être touché ?"],
[2,14,19,77,40,14,"Marcher sur les eaux","Jésus nourrit cinq mille hommes puis marche sur la mer ; Pierre avance, doute et s'enfonce ; ton chemin passait par la mer ; Dieu ouvre la mer devant Israël.","Où ai-je besoin de garder les yeux sur Jésus pour ne pas couler ?"],
[8,1,19,67,40,15,"La foi d'une étrangère","Jésus dénonce les traditions sans cœur, puis une Cananéenne insiste : même les petits chiens mangent les miettes ; que tous les peuples te louent ; Ruth la Moabite s'attache au Dieu d'Israël.","Est-ce que j'insiste dans la prière comme cette femme ?"],
[2,16,19,78,41,6,"Donnez-leur vous-mêmes à manger","Jésus a pitié de la foule sans berger et multiplie cinq pains ; il fit pleuvoir la manne pour les nourrir ; Dieu donne la manne au désert, jour après jour.","Qu'est-ce que je peux mettre, même peu, dans les mains de Jésus ?"],
[23,29,19,139,41,7,"Ephphata, ouvre-toi","Jésus montre que le mal vient du cœur, puis ouvre les oreilles d'un sourd : Ephphata ; sonde-moi, ô Dieu, et connais mon cœur ; Ésaïe : ce peuple m'honore des lèvres, mais un jour les sourds entendront.","Où ai-je besoin que Jésus « ouvre » mon cœur ?"],
[24,5,19,106,41,8,"Ne voyez-vous pas encore ?","Après la deuxième multiplication, les disciples s'inquiètent du pain, puis un aveugle est guéri en deux temps ; ils oublièrent vite ses œuvres ; Jérémie : peuple qui a des yeux et ne voit pas.","Qu'est-ce que Dieu a déjà fait, que j'oublie quand j'ai peur ?"],
[1,24,19,42,43,4,"La femme au puits","Jésus demande à boire à une Samaritaine et lui offre l'eau vive ; mon âme a soif de Dieu ; au bord d'un puits, le serviteur d'Abraham rencontre Rebecca.","De quoi ai-je soif, au fond ?"],
[12,17,19,95,43,4,"En esprit et en vérité","Les vrais adorateurs adoreront le Père en esprit et en vérité, et les champs sont déjà blancs pour la moisson ; venez, prosternons-nous ; les Samaritains servaient à la fois l'Éternel et leurs idoles.","Mon adoration est-elle « en esprit et en vérité » ?"],
[5,2,19,38,43,5,"Veux-tu être guéri ?","Près de la piscine, un homme paralysé depuis trente-huit ans entend : lève-toi et marche ; le psalmiste malade crie vers Dieu ; Israël avait erré trente-huit ans dans le désert.","Est-ce que je veux vraiment être guéri de ce qui me paralyse ?"],
[16,9,19,81,43,6,"Le pain du ciel","Après la multiplication, Jésus dit : je suis le pain de vie, celui qui vient à moi n'aura jamais faim ; je te nourrirais du meilleur froment ; Néhémie rappelle le pain que Dieu donnait du ciel.","De quoi est-ce que je nourris mon âme ?"],
[11,18,19,73,43,6,"À qui irions-nous ?","Beaucoup quittent Jésus, et Pierre répond : à qui irions-nous ? tu as les paroles de la vie éternelle ; quel autre que toi ai-je au ciel ? ; Élie : jusqu'à quand boiterez-vous des deux côtés ?","Qu'est-ce qui me retient de partir quand c'est difficile ?"],
[23,42,19,13,43,9,"J'étais aveugle, maintenant je vois","Un aveugle de naissance est guéri et témoigne malgré l'opposition : je sais une chose, j'étais aveugle et maintenant je vois ; éclaire mes yeux ; Ésaïe : le serviteur ouvrira les yeux des aveugles.","Qu'est-ce que Jésus m'a fait voir que je ne voyais pas ?"],
[23,26,19,9,42,7,"Ne pleure pas","Jésus admire la foi d'un centurion, puis rend à une veuve son fils unique : ne pleure pas ; tu n'abandonnes pas ceux qui te cherchent ; Ésaïe : tes morts revivront.","Quelle larme ai-je besoin de confier à Jésus ?"],
[10,12,22,1,42,7,"Elle a beaucoup aimé","Une femme pécheresse verse son parfum sur les pieds de Jésus : celui à qui l'on pardonne beaucoup aime beaucoup ; ton nom est un parfum répandu ; Nathan raconte une histoire, et David reconnaît sa faute.","Est-ce que je mesure combien j'ai été pardonné ?"],
[23,5,19,80,42,13,"Le figuier et la femme courbée","Jésus raconte le figuier qui ne porte pas de fruit, puis redresse une femme courbée depuis dix-huit ans ; Dieu, viens visiter cette vigne ; Ésaïe chante la vigne qui ne donne que des raisins sauvages.","Quel fruit Dieu attend-il de ma vie ?"],
[3,14,19,116,42,17,"Un seul revient dire merci","Dix lépreux sont guéris en chemin, et un seul, un Samaritain, revient remercier ; que rendrai-je à l'Éternel pour tous ses bienfaits ? ; la loi prévoyait de se montrer au prêtre pour être déclaré pur.","Pour quoi n'ai-je pas encore dit merci à Dieu ?"],
[24,33,19,40,41,10,"Que veux-tu que je fasse pour toi ?","Bartimée crie malgré ceux qui veulent le faire taire, et Jésus demande : que veux-tu que je fasse pour toi ? ; il s'est penché vers moi et il a entendu mon cri ; Jérémie : invoque-moi, et je te répondrai.","Que répondrais-je si Jésus me posait cette question ?"],
[26,37,19,90,43,11,"Je suis la résurrection et la vie","Lazare est mort depuis quatre jours, et Jésus l'appelle hors du tombeau ; Moïse prie : tu fais retourner l'homme à la poussière ; Ézéchiel voit les ossements desséchés revenir à la vie.","Est-ce que je crois que Jésus est la résurrection, même devant la mort ?"],
[1,23,19,56,43,11,"Jésus pleura","Devant la tombe de son ami, Jésus pleure avec Marthe et Marie ; tu recueilles mes larmes dans ton outre ; Abraham pleure Sara et achète un tombeau.","Est-ce que je crois que Jésus pleure avec moi ?"],
[23,28,19,18,40,16,"Tu es le Christ","Pierre confesse : tu es le Christ, le Fils du Dieu vivant, et Jésus répond : sur ce rocher je bâtirai mon Église ; l'Éternel est mon rocher ; Ésaïe : je pose en Sion une pierre éprouvée.","Qui est Jésus pour moi, aujourd'hui ?"],
[1,22,21,2,40,16,"Perdre sa vie pour la trouver","Jésus annonce sa croix, Pierre proteste, et Jésus dit : que sert-il de gagner le monde si l'on perd son âme ? ; j'ai fait de grandes choses, et tout était vanité ; Abraham remet tout à Dieu sur la montagne.","Qu'est-ce que je risque de gagner en perdant l'essentiel ?"],
[2,34,19,97,40,17,"La transfiguration","Sur la montagne, le visage de Jésus resplendit, Moïse et Élie paraissent, et la voix dit : écoutez-le ; nuées et obscurité l'environnent ; le visage de Moïse rayonnait après avoir parlé avec Dieu.","Ai-je pris un temps pour contempler la gloire de Jésus ?"],
[1,15,19,62,41,9,"Je crois, aide-moi","Un père supplie : je crois, viens au secours de mon manque de foi, puis Jésus place un enfant au milieu des disciples ; mon âme se confie en Dieu seul ; Abram croit Dieu sous les étoiles.","Où ma foi a-t-elle besoin d'aide ?"],
[3,23,19,63,43,7,"Fleuves d'eau vive","À la fête des Cabanes, Jésus crie : si quelqu'un a soif, qu'il vienne à moi et qu'il boive ; mon âme a soif de toi dans une terre aride ; la loi instituait cette fête de la récolte.","Vers quoi est-ce que je cours quand j'ai soif ?"],
[5,1,20,18,43,7,"Jamais homme n'a parlé ainsi","La foule est divisée, et les gardes reviennent sans lui : jamais homme n'a parlé comme cet homme ; répondre avant d'avoir écouté, c'est une folie ; Moïse demandait aux juges d'écouter avant de juger.","Est-ce que je juge Jésus sur des préjugés ou après l'avoir écouté ?"],
[2,13,19,43,43,8,"La lumière du monde","Jésus relève la femme accusée : moi non plus, je ne te condamne pas, va ; puis il dit : je suis la lumière du monde ; envoie ta lumière et ta vérité ; Dieu guidait Israël par une colonne de feu.","Qu'est-ce que la lumière de Jésus éclaire chez moi ?"],
[2,3,19,102,43,8,"Avant qu'Abraham fût, je suis","Jésus dit : la vérité vous rendra libres, et avant qu'Abraham fût, je suis ; toi, tu restes le même, tes années ne finissent pas ; au buisson ardent, Dieu se nommait : JE SUIS.","De quoi la vérité de Jésus veut-elle me libérer ?"],
[24,23,19,28,43,10,"Le bon berger","Je suis le bon berger, le bon berger donne sa vie pour ses brebis ; sois leur berger, porte-les pour toujours ; Jérémie : malheur aux bergers qui dispersent, je rassemblerai mes brebis.","Est-ce que je reconnais la voix du berger ?"],
[1,48,19,61,43,10,"Personne ne les arrachera de ma main","Je suis la porte ; je donne la vie éternelle, personne ne les arrachera de ma main ; je me réfugie à l'abri de tes ailes ; Jacob bénit au nom du Dieu qui a été son berger toute sa vie.","Est-ce que je me sais en sécurité dans la main de Jésus ?"],
[24,6,19,55,40,11,"Venez à moi, vous qui êtes fatigués","Jésus appelle : venez à moi, vous tous qui êtes fatigués, et vous trouverez du repos ; remets ton fardeau à l'Éternel ; Jérémie : marchez sur les anciens sentiers, et vous trouverez le repos de vos âmes.","Quel fardeau vais-je déposer auprès de Jésus ?"],
[23,35,19,19,40,11,"Révélé aux tout-petits","Jésus répond à Jean-Baptiste : les aveugles voient, les boiteux marchent, et il loue le Père de révéler ces choses aux tout-petits ; la loi de l'Éternel rend sage le simple ; Ésaïe annonçait ces signes.","Est-ce que je viens à Dieu comme un tout-petit, ou comme un savant ?"],
[32,2,19,99,40,12,"Plus que Jonas","Jésus est le Seigneur du sabbat, et il annonce le signe de Jonas : trois jours dans la terre ; il est saint, l'Éternel notre Dieu ; Jonas prie du ventre du poisson.","Quel signe est-ce que j'attends encore pour croire ?"],
[26,36,19,87,43,3,"Naître de nouveau","Nicodème vient de nuit, et Jésus lui dit : il faut naître d'eau et d'Esprit ; de chacun on dira : celui-ci est né à Sion ; Ézéchiel : je vous donnerai un cœur nouveau et un esprit nouveau.","Qu'est-ce qui est nouveau en moi depuis que je suis à Christ ?"],
[4,21,22,8,43,3,"Dieu a tant aimé le monde","Comme Moïse éleva le serpent, le Fils doit être élevé : Dieu a tant aimé le monde qu'il a donné son Fils ; l'amour est fort comme la mort ; au désert, ceux qui regardaient le serpent de bronze vivaient.","Est-ce que je crois que ce verset parle de moi ?"],
[39,2,20,5,40,19,"Ce que Dieu a uni","Jésus rappelle le mariage voulu au commencement, accueille les enfants, et le jeune homme riche s'en va triste ; fais ta joie de la femme de ta jeunesse ; Malachie : ne soyez pas infidèles envers la femme de votre jeunesse.","Comment j'honore les engagements pris devant Dieu ?"],
[24,7,19,69,41,11,"Une maison de prière","Jésus maudit un figuier sans fruit et chasse les marchands du temple : ma maison sera une maison de prière ; le zèle de ta maison me dévore ; Jérémie dénonçait un temple devenu caverne de voleurs.","Ma vie est-elle une maison de prière ?"],
[24,9,19,122,42,19,"Jésus pleure sur Jérusalem","En approchant de la ville, Jésus pleure : si tu avais compris ce qui donne la paix ! ; demandez la paix de Jérusalem ; Jérémie voulait pleurer jour et nuit sur son peuple.","Sur qui Jésus m'invite-t-il à pleurer et à prier ?"],
[2,30,22,4,43,12,"Le parfum répandu","Six jours avant la Pâque, Marie verse sur Jésus un parfum de grand prix, et toute la maison en est remplie ; le Cantique chante le jardin des parfums ; la loi décrivait l'huile sainte, réservée à Dieu.","Qu'est-ce que je « répands » pour Jésus sans compter ?"],
[5,10,20,11,41,12,"Le premier commandement","Un scribe demande le plus grand commandement, puis une veuve donne tout ce qu'elle a ; celui qui donne largement sera rassasié ; Moïse : que demande l'Éternel, sinon de l'aimer de tout ton cœur ?","Qu'est-ce que je donne qui me coûte vraiment ?"],
[14,36,19,110,42,20,"Le Seigneur de David","Jésus raconte les vignerons qui tuent le fils, et montre que le Messie est le Seigneur de David ; le Seigneur a dit à mon Seigneur : assieds-toi à ma droite ; Dieu envoyait ses messagers, et on se moquait d'eux.","Est-ce que je donne à Jésus la place qui lui revient ?"],
[23,1,19,50,40,23,"Malheur aux hypocrites","Jésus dénonce une religion de façade : vous nettoyez l'extérieur et laissez l'intérieur sale ; Dieu reproche un culte sans obéissance ; Ésaïe : vos fêtes me pèsent, lavez-vous, apprenez à faire le bien.","Où suis-je différent dehors et dedans ?"],
[27,9,19,46,40,24,"Ne vous laissez pas troubler","Jésus annonce la destruction du temple, des guerres et de faux messies : ne soyez pas troublés ; Dieu est notre refuge, nous ne craindrons pas quand la terre tremble ; Daniel annonçait les temps de désolation.","Qu'est-ce qui me trouble dans l'actualité, que je peux remettre à Dieu ?"],
[1,6,19,39,40,24,"Comme aux jours de Noé","Personne ne connaît le jour : veillez, comme aux jours de Noé où l'on vivait sans se douter de rien ; fais-moi connaître la mesure de mes jours ; Noé construit l'arche pendant que le monde continue sa vie.","Est-ce que je vis comme quelqu'un qui attend le retour du Seigneur ?"],
[27,7,19,93,41,13,"Le Fils de l'homme sur les nuées","Le ciel et la terre passeront, mais mes paroles ne passeront pas ; on verra le Fils de l'homme venir sur les nuées ; l'Éternel règne, revêtu de majesté ; Daniel voyait un Fils d'homme recevoir un règne éternel.","Sur quelle parole de Jésus vais-je m'appuyer aujourd'hui ?"],
[27,3,19,4,42,21,"Pas un cheveu ne sera perdu","Jésus annonce les persécutions : pas un cheveu de votre tête ne sera perdu, c'est par votre persévérance que vous sauverez vos âmes ; je me couche et je m'endors en paix ; dans la fournaise, pas un cheveu des trois amis n'est brûlé.","Est-ce que je crois que Dieu garde même les détails de ma vie ?"],
[1,8,21,3,43,12,"Si le grain ne meurt","Si le grain de blé ne tombe en terre et ne meurt, il reste seul ; s'il meurt, il porte beaucoup de fruit ; il y a un temps pour planter et un temps pour arracher ; Dieu promet : tant que la terre durera, semailles et moissons ne cesseront pas.","Qu'est-ce qui doit « mourir » en moi pour porter du fruit ?"],
[9,25,20,15,43,13,"Il leur lava les pieds","Jésus prend un linge et lave les pieds de ses disciples : je vous ai donné un exemple ; l'humilité précède la gloire ; Abigaïl se disait prête à laver les pieds des serviteurs de David.","Aux pieds de qui Jésus m'envoie-t-il servir ?"],
[10,15,20,17,43,13,"Aimez-vous les uns les autres","Judas sort dans la nuit, et Jésus donne le commandement nouveau : aimez-vous comme je vous ai aimés ; l'ami aime en tout temps ; David, trahi par son conseiller, monte en pleurant le mont des Oliviers.","À quoi verra-t-on que je suis disciple de Jésus ?"],
[2,25,19,84,43,14,"Une place pour vous","Que votre cœur ne se trouble pas : il y a beaucoup de demeures dans la maison de mon Père, je suis le chemin, la vérité et la vie ; que tes demeures sont aimables ; Dieu demandait un sanctuaire pour habiter au milieu de son peuple.","Qu'est-ce qui trouble mon cœur, et que Jésus veut apaiser ?"],
[23,32,19,104,43,14,"Je ne vous laisserai pas orphelins","Jésus promet un autre Consolateur, l'Esprit de vérité, et donne sa paix ; tu envoies ton souffle, ils sont créés ; Ésaïe : quand l'Esprit sera répandu d'en haut, l'œuvre de la justice sera la paix.","Est-ce que je compte sur l'Esprit au quotidien ?"],
[5,7,19,101,43,14,"Si vous m'aimez","Si quelqu'un m'aime, il gardera ma parole, et nous ferons notre demeure chez lui ; je marcherai avec un cœur intègre ; Moïse : Dieu garde son alliance avec ceux qui l'aiment et gardent ses commandements.","Comment mon amour pour Jésus se voit-il dans mon obéissance ?"],
[23,27,19,128,43,15,"Je suis le cep","Je suis le cep, vous êtes les sarments : demeurez en moi, sans moi vous ne pouvez rien faire ; ta femme est comme une vigne féconde ; Ésaïe : l'Éternel garde sa vigne et l'arrose sans cesse.","Qu'est-ce qui m'aide à demeurer en Jésus ?"],
[9,18,20,27,43,15,"Je vous appelle amis","Il n'y a pas de plus grand amour que de donner sa vie pour ses amis, et je vous appelle mes amis ; un ami proche vaut mieux qu'un frère éloigné ; Jonathan aimait David comme lui-même.","Est-ce que je vis mon lien avec Jésus comme une amitié ?"],
[24,20,19,129,43,15,"Si le monde vous hait","Si le monde vous hait, sachez qu'il m'a haï avant vous, mais l'Esprit rendra témoignage ; ils m'ont souvent attaqué, mais ils ne m'ont pas vaincu ; Jérémie, moqué, ne peut pourtant pas se taire.","Comment je vis l'hostilité à cause de ma foi ?"],
[23,66,19,66,43,16,"Votre tristesse se changera en joie","Comme la femme qui accouche, vous serez tristes, mais votre tristesse se changera en joie : j'ai vaincu le monde ; nous avons passé par le feu et par l'eau, puis tu nous as fait sortir dans l'abondance ; Ésaïe : comme une mère console, je vous consolerai.","Quelle tristesse ai-je besoin de vivre avec l'espérance de la joie ?"],
[4,6,19,17,43,17,"Jésus prie pour les siens","Jésus lève les yeux au ciel : la vie éternelle, c'est qu'ils te connaissent ; garde-les du mal ; garde-moi comme la prunelle de l'œil ; Aaron bénissait le peuple : que l'Éternel te garde.","Est-ce que je sais que Jésus prie pour moi ?"],
[14,30,19,133,43,17,"Qu'ils soient un","Jésus prie pour ceux qui croiront plus tard : que tous soient un, afin que le monde croie ; qu'il est doux pour des frères de vivre unis ; à la Pâque d'Ézéchias, Dieu donne au peuple un même cœur.","Que puis-je faire pour l'unité de l'Église ?"],
[2,24,19,111,40,26,"Ceci est mon sang de l'alliance","Jésus prend le pain et la coupe : ceci est mon corps, ceci est mon sang, le sang de l'alliance ; il se souvient toujours de son alliance ; Moïse aspergeait le peuple du sang de l'alliance au Sinaï.","Que représente pour moi la cène quand je la prends ?"],
[1,32,19,143,41,14,"Que ta volonté soit faite","Au jardin de Gethsémané, Jésus prie dans l'angoisse : Abba, Père, non pas ce que je veux, mais ce que tu veux ; enseigne-moi à faire ta volonté ; Jacob lutta toute une nuit avec Dieu.","Où ai-je besoin de dire : non pas ce que je veux, mais ce que tu veux ?"],
[2,32,20,29,42,22,"Le reniement de Pierre","Pierre jure qu'il ne connaît pas Jésus, le coq chante, Jésus le regarde, et Pierre pleure amèrement ; la crainte des hommes tend un piège ; sous la pression du peuple, Aaron fabrique le veau d'or.","Devant qui ai-je honte de dire que je suis à Jésus ?"],
[27,6,19,35,43,18,"Mon royaume n'est pas de ce monde","Jésus est arrêté, interrogé, et déclare à Pilate : mon royaume n'est pas de ce monde ; de faux témoins se lèvent contre moi ; Daniel, innocent, est livré par jalousie.","Est-ce que Jésus est le roi de ma vie, même quand cela coûte ?"],
[23,50,18,16,40,27,"Le procès injuste","Jésus se tait devant ses accusateurs, la foule choisit Barabbas, et les soldats se moquent de lui ; Job : ils me frappent, mais mon témoin est dans les cieux ; Ésaïe : j'ai livré mon dos à ceux qui me frappaient.","Que me dit le silence de Jésus devant l'injustice ?"],
[23,53,19,22,40,27,"Pourquoi m'as-tu abandonné ?","Sur la croix, Jésus crie les premiers mots du psaume 22, la terre tremble et le voile du temple se déchire ; mon Dieu, mon Dieu, pourquoi m'as-tu abandonné ? ; Ésaïe : il a été blessé pour nos fautes.","Qu'est-ce que Jésus a porté à ma place ?"],
[3,16,18,19,41,15,"Couronné d'épines","Les soldats habillent Jésus de pourpre et le couronnent d'épines, puis le crucifient hors de la ville ; Job : je sais que mon rédempteur est vivant ; au grand jour du pardon, le bouc emportait les fautes hors du camp.","Est-ce que je laisse Jésus emporter mes fautes au loin ?"],
[2,26,19,31,41,15,"Le voile déchiré","À la mort de Jésus, le voile du temple se déchire de haut en bas, et un centurion déclare : vraiment, cet homme était Fils de Dieu ; entre tes mains, je remets mon esprit ; le voile du tabernacle séparait le lieu très saint.","Est-ce que j'ose entrer dans la présence de Dieu, maintenant que le voile est déchiré ?"],
[4,35,18,33,42,23,"Père, pardonne-leur","Jésus prie pour ceux qui le crucifient : ils ne savent pas ce qu'ils font ; Élihou : j'ai trouvé une rançon, délivre-le de la fosse ; la loi offrait un refuge à celui qui avait tué sans le savoir.","Qui ai-je besoin de pardonner, comme Jésus sur la croix ?"],
[1,3,18,14,42,23,"Aujourd'hui, tu seras avec moi","Un malfaiteur crucifié supplie : Jésus, souviens-toi de moi, et Jésus répond : aujourd'hui, tu seras avec moi dans le paradis ; Job : l'homme qui meurt revivra-t-il ? ; Dieu avait fermé le jardin, mais promis un vainqueur.","Est-ce que je crois que la grâce peut atteindre quelqu'un jusqu'au dernier instant ?"],
[4,9,18,9,43,19,"Tout est accompli","Pilate présente Jésus : voici l'homme ; sur la croix, Jésus dit : tout est accompli, et on ne lui brise aucun os ; Job cherchait un arbitre entre Dieu et lui ; à la Pâque, on ne devait briser aucun os de l'agneau.","Qu'est-ce que « tout est accompli » libère dans ma vie ?"],
[10,21,18,2,43,19,"Au pied de la croix","Marie se tient près de la croix, et Jésus la confie à Jean : voici ton fils, voici ta mère ; les amis de Job restent sept jours près de lui en silence ; Ritspa veille longtemps sur ses fils morts.","Auprès de qui Dieu m'appelle-t-il à rester, même sans mots ?"],
[38,12,18,17,43,19,"Le côté percé","Un soldat perce le côté de Jésus, il en sort du sang et de l'eau, et Joseph et Nicodème le déposent dans un tombeau neuf ; Job : le séjour des morts sera ma maison ; Zacharie : ils regarderont vers celui qu'ils ont percé.","Que me dit le silence du samedi, quand Dieu semble absent ?"],
[1,12,19,3,40,28,"Il est ressuscité !","Les femmes trouvent le tombeau vide : il n'est pas ici, il est ressuscité ; puis Jésus envoie les siens vers toutes les nations ; je me suis couché, je me réveille, car l'Éternel me soutient ; Dieu promettait à Abraham la bénédiction de toutes les familles de la terre.","Qu'est-ce que la résurrection change à ma manière de vivre ?"],
[23,52,19,47,41,16,"Allez par tout le monde","Les femmes fuient tremblantes, puis Jésus apparaît et envoie : allez par tout le monde annoncer la bonne nouvelle ; peuples, battez des mains, Dieu est roi de toute la terre ; Ésaïe : qu'ils sont beaux, les pieds de celui qui annonce la paix.","À qui pourrais-je annoncer la bonne nouvelle cette semaine ?"],
[12,13,19,21,42,24,"Pourquoi chercher parmi les morts ?","Des femmes apportent des aromates, et les anges disent : pourquoi cherchez-vous parmi les morts celui qui est vivant ? ; il te demandait la vie, tu la lui as donnée ; un mort reprend vie en touchant les os d'Élisée.","Où est-ce que je cherche la vie au mauvais endroit ?"],
[12,22,19,105,42,24,"Notre cœur ne brûlait-il pas ?","Deux disciples marchent tristes vers Emmaüs, Jésus leur explique les Écritures, puis se fait reconnaître en rompant le pain ; souvenez-vous des merveilles qu'il a faites ; sous Josias, le livre de la loi retrouvé bouleverse le roi.","Quand la Parole a-t-elle fait « brûler » mon cœur ?"],
[3,9,19,134,42,24,"Il les bénit en montant au ciel","Jésus ressuscité mange avec eux, leur ouvre l'intelligence des Écritures, puis les bénit en s'élevant au ciel, et ils repartent pleins de joie ; levez les mains et bénissez l'Éternel ; Aaron levait les mains pour bénir le peuple, et la gloire apparut.","Est-ce que je vis sous la bénédiction de Jésus ?"],
[23,43,22,5,43,20,"Marie !","Marie de Magdala pleure au tombeau, et Jésus l'appelle par son nom ; elle le reconnaît : Rabbouni ! ; dans le Cantique, la bien-aimée cherche celui qu'elle aime ; Ésaïe : je t'ai appelé par ton nom, tu es à moi.","Ai-je entendu Jésus m'appeler par mon nom ?"],
[7,6,19,29,43,20,"Mon Seigneur et mon Dieu","Jésus se montre aux disciples enfermés : la paix soit avec vous, et il souffle sur eux l'Esprit ; Thomas doute, puis s'écrie : mon Seigneur et mon Dieu ; l'Éternel bénit son peuple par la paix ; Gédéon doutait, et Dieu lui dit : la paix soit avec toi.","Qu'est-ce que je dis à Jésus quand mes doutes se dissipent ?"],
[6,1,19,71,43,21,"M'aimes-tu ?","Au bord du lac, autour d'un feu de braises, Jésus demande trois fois à Pierre : m'aimes-tu ? et lui confie ses brebis ; ô Dieu, tu m'as instruit dès ma jeunesse, ne m'abandonne pas dans ma vieillesse ; Dieu confie le peuple à Josué après Moïse.","Si Jésus me demandait aujourd'hui « m'aimes-tu ? », que répondrais-je ?"],
[28,13,19,57,46,15,"Christ est ressuscité","Paul rappelle l'Évangile : Christ est mort, il a été enseveli, il est ressuscité, il est apparu ; sans cela, notre foi serait vaine ; réveille-toi, ma gloire, je réveillerai l'aurore ; Osée : ô mort, où est ta peste ?","Ma foi repose-t-elle vraiment sur la résurrection ?"],
[1,5,21,12,46,15,"Ô mort, où est ta victoire ?","Le corps semé dans la faiblesse ressuscite dans la gloire : la mort est engloutie dans la victoire, soyez donc fermes ; la poussière retourne à la terre, et l'esprit à Dieu ; Hénoc marchait avec Dieu, et Dieu le prit.","Comment l'espérance de la résurrection me rend-elle ferme aujourd'hui ?"],
[38,14,19,123,44,1,"Il reviendra de la même manière","Jésus monte au ciel depuis le mont des Oliviers, les anges annoncent qu'il reviendra, et les disciples attendent en priant ; nos yeux sont tournés vers l'Éternel ; Zacharie : ses pieds se poseront sur le mont des Oliviers.","Comment j'attends : en regardant le ciel, ou en priant et en témoignant ?"],
[29,2,19,117,44,2,"L'Esprit répandu","À la Pentecôte, l'Esprit descend comme un feu, et chacun entend les merveilles de Dieu dans sa langue ; nations, louez toutes l'Éternel ; Joël : je répandrai mon Esprit sur toute chair.","Qu'est-ce que l'Esprit veut faire à travers moi ?"],
[1,11,19,127,44,2,"Ils persévéraient ensemble","Trois mille personnes se convertissent et persévèrent dans l'enseignement, la communion, le partage du pain et la prière ; si l'Éternel ne bâtit la maison… ; à Babel, les hommes bâtissaient pour eux-mêmes et ont été dispersés.","Laquelle de ces quatre choses manque le plus à ma vie de foi ?"],
[10,9,19,20,44,3,"Au nom de Jésus, lève-toi","Pierre dit au boiteux : je n'ai ni argent ni or, mais ce que j'ai, je te le donne : au nom de Jésus, marche ! ; nous nous appuyons sur le nom de l'Éternel ; David accueille Mephiboseth, boiteux, à sa table.","Qu'est-ce que j'ai reçu de Dieu, que je pourrais donner aujourd'hui ?"],
[30,7,19,11,44,4,"Nous ne pouvons pas nous taire","Devant le tribunal, Pierre et Jean, hommes simples, déclarent : il n'y a de salut en aucun autre nom, nous ne pouvons pas ne pas parler ; c'est en l'Éternel que je me réfugie ; Amos, simple berger, parle malgré l'interdiction du prêtre.","Qu'est-ce que j'ai vu et entendu, que je ne peux pas garder pour moi ?"],
[5,15,19,114,44,4,"Le lieu trembla","Menacée, l'Église prie, le lieu tremble, et ils partagent tout : il n'y avait parmi eux aucun nécessiteux ; terre, tremble devant le Seigneur ; Moïse : qu'il n'y ait pas de pauvre parmi vous.","Comment ma prière et mon argent se rejoignent-ils ?"],
[3,10,20,12,44,5,"La vérité devant Dieu","Ananias et Saphira mentent sur leur don ; puis les apôtres, libérés de prison, déclarent : il faut obéir à Dieu plutôt qu'aux hommes ; les lèvres menteuses sont en horreur à l'Éternel ; Nadab et Abihu avaient offert à Dieu un feu étranger.","Y a-t-il une part de mensonge dans ma façon de paraître ?"],
[2,18,19,82,44,6,"Servir aux tables","Des veuves sont oubliées, et l'Église choisit sept hommes pleins d'Esprit pour servir, tandis que les apôtres se consacrent à la prière et à la Parole ; défendez le faible et l'orphelin ; Jéthro conseille à Moïse de partager la charge.","Quel service concret puis-je prendre dans mon Église ?"],
[1,37,19,136,44,7,"L'histoire racontée par Étienne","Étienne raconte l'histoire d'Israël : Abraham, Joseph rejeté puis élevé, Moïse rejeté puis envoyé ; le psaume répète : car sa bonté dure toujours ; Joseph est vendu par ses frères.","Est-ce que je reconnais Jésus dans toute l'histoire de la Bible ?"],
[14,24,18,13,44,7,"Le ciel ouvert","Lapidé, Étienne voit le ciel ouvert et prie : Seigneur, ne leur compte pas ce péché ; Job : même s'il me tue, j'espérerai en lui ; le prêtre Zacharie fut lapidé dans la cour du temple.","Est-ce que je pourrais pardonner comme Étienne ?"],
[23,56,19,149,44,8,"Qu'est-ce qui m'empêche d'être baptisé ?","Dispersés par la persécution, les croyants annoncent partout la Parole, et Philippe explique Ésaïe à un eunuque éthiopien qui demande le baptême ; que les enfants de Sion se réjouissent ; Ésaïe : que l'eunuque ne dise plus : je suis un arbre sec.","Qui pourrais-je aider à comprendre ce qu'il lit dans la Bible ?"],
[9,3,18,36,44,9,"Saul, pourquoi me persécutes-tu ?","Sur la route de Damas, une lumière renverse Saul et Jésus lui parle ; aveugle trois jours, il est accueilli par Ananias : frère Saul ; Élihou : Dieu ouvre l'oreille de l'homme par l'épreuve ; le jeune Samuel entend Dieu l'appeler par son nom.","Qui est le « Saul » pour qui je ne prie plus ?"],
[8,2,20,31,44,9,"Barnabas et Dorcas","Barnabas prend Saul sous sa protection quand tous ont peur de lui, et Dorcas, qui faisait tant de bien, revient à la vie ; la femme de valeur tend la main au pauvre ; Boaz prend soin de Ruth l'étrangère.","Qui pourrais-je encourager comme Barnabas ?"],
[3,11,19,148,44,10,"Ce que Dieu a purifié","Pierre voit une nappe pleine d'animaux impurs : ce que Dieu a purifié, ne le déclare pas impur ; louez l'Éternel, rois de la terre et tous les peuples ; la loi distinguait le pur et l'impur.","Qui ai-je du mal à accueillir comme Dieu l'accueille ?"],
[32,3,19,108,44,10,"L'Esprit sur les nations","Chez Corneille, l'officier romain, l'Esprit descend sur ceux qui écoutent : Dieu ne fait pas de favoritisme ; je te louerai parmi les peuples ; Ninive, la ville païenne, se convertit à la prédication de Jonas.","Est-ce que je crois que l'Évangile est pour tous, sans exception ?"],
[1,45,19,125,44,11,"Appelés chrétiens","À Antioche, des gens de toutes origines croient, Barnabas les encourage à rester attachés au Seigneur, et pour la première fois on les appelle chrétiens ; ceux qui se confient en l'Éternel sont inébranlables ; Joseph accueille et nourrit sa famille pendant la famine.","Est-ce que le nom de chrétien se voit dans ma vie ?"],
[23,37,19,124,44,12,"L'Église priait","Pierre est en prison, l'Église prie sans cesse, et un ange le libère ; Hérode, qui se laisse acclamer comme un dieu, est frappé ; le filet s'est rompu et nous avons été délivrés ; Ézéchias prie, et l'ange de l'Éternel frappe l'armée ennemie.","Pour qui, « en prison », vais-je prier sans cesse ?"],
[23,6,19,44,44,13,"Me voici, envoie-moi","L'Église d'Antioche jeûne et prie, et l'Esprit dit : mettez à part Barnabas et Saul pour l'œuvre ; nos pères nous ont raconté ce que tu as fait ; Ésaïe entend : qui enverrai-je ? et répond : me voici, envoie-moi.","Pour quelle œuvre Dieu pourrait-il me mettre à part ?"],
[24,10,19,115,44,14,"Des hommes comme vous","À Lystre, on prend Paul et Barnabas pour des dieux, et ils crient : nous sommes des hommes comme vous, tournez-vous vers le Dieu vivant ; leurs idoles sont l'œuvre des hommes ; Jérémie : les idoles sont des épouvantails, l'Éternel est le vrai Dieu.","Est-ce que je cherche à être admiré plutôt qu'à montrer Dieu ?"],
[30,9,20,20,44,15,"Sauvés par la grâce, ensemble","Un conflit éclate sur la loi de Moïse ; l'Église se réunit, écoute, discute et décide : nous sommes sauvés par la grâce du Seigneur Jésus ; les projets s'affermissent par le conseil ; Jacques cite Amos : je relèverai la tente de David, pour que les nations cherchent le Seigneur.","Comment je vis un désaccord dans l'Église ?"],
[23,30,19,37,44,16,"La porte de la Macédoine","L'Esprit empêche Paul d'aller en Asie, puis une vision l'appelle en Macédoine, où le Seigneur ouvre le cœur de Lydie ; recommande ton sort à l'Éternel ; Ésaïe : tes oreilles entendront : voici le chemin, marchez-y.","Quelle porte fermée m'a conduit vers une porte ouverte ?"],
[1,39,18,35,44,16,"Des chants à minuit","Battus et enchaînés, Paul et Silas chantent à minuit, la prison tremble, et le geôlier demande : que dois-je faire pour être sauvé ? ; Élihou parle du Dieu qui donne des chants dans la nuit ; Joseph, en prison, restait fidèle et Dieu était avec lui.","Est-ce que je peux louer Dieu au milieu de ma « nuit » ?"],
[16,8,20,1,44,17,"Ils examinaient les Écritures","À Thessalonique, on accuse Paul de mettre le monde sens dessus dessous ; à Bérée, on examine chaque jour les Écritures pour vérifier ; la sagesse crie dans les rues : écoutez ; Esdras lit la loi, et on l'explique au peuple.","Est-ce que je vérifie dans la Bible ce que j'entends ?"],
[23,44,18,12,44,17,"Au dieu inconnu","À Athènes, Paul part d'un autel « au dieu inconnu » : c'est en lui que nous avons la vie, le mouvement et l'être ; Job : il tient dans sa main la vie de tout ce qui vit ; Ésaïe se moque du dieu fait avec la moitié d'un morceau de bois.","Comment parler de Dieu à quelqu'un qui ne le connaît pas ?"],
[23,41,21,4,44,18,"Ne crains pas, parle","À Corinthe, Paul travaille avec Aquilas et Priscille, puis le Seigneur lui dit : ne crains pas, parle, car je suis avec toi ; deux valent mieux qu'un ; Ésaïe : ne crains rien, car je suis avec toi.","Avec qui pourrais-je servir en équipe ?"],
[5,18,19,135,44,19,"Les livres de magie brûlés","À Éphèse, l'Évangile est si puissant que des croyants brûlent leurs livres de magie, et les fabricants d'idoles provoquent une émeute ; leurs idoles sont de l'argent et de l'or ; Moïse : qu'on ne trouve chez toi ni devin ni magicien.","Qu'est-ce que je dois « brûler » pour être libre en Christ ?"],
[9,12,19,26,44,20,"Servir avec humilité","Paul fait ses adieux aux anciens d'Éphèse : j'ai servi le Seigneur en toute humilité, je ne vous ai rien caché ; je marche dans l'intégrité ; Samuel, avant de partir, demande : à qui ai-je fait du tort ?","Que voudrais-je pouvoir dire de mon service quand je partirai ?"],
[26,33,20,22,44,20,"Plus de bonheur à donner","Paul demande aux anciens de veiller sur le troupeau, et rappelle la parole de Jésus : il y a plus de bonheur à donner qu'à recevoir ; l'homme bienveillant partage son pain avec le pauvre ; Ézéchiel est établi sentinelle pour son peuple.","Qu'est-ce que je pourrais donner cette semaine ?"],
[24,26,18,23,44,21,"Prêt à mourir","On supplie Paul de ne pas monter à Jérusalem, et il répond : je suis prêt à mourir pour le nom du Seigneur Jésus ; puis il est arrêté au temple ; Job : il connaît le chemin que je prends ; Jérémie, menacé de mort, ne retire pas une parole.","Jusqu'où suis-je prêt à suivre Jésus ?"],
[26,2,19,120,44,22,"Raconter son histoire","Devant la foule en colère, Paul raconte simplement comment Jésus l'a rencontré et changé ; je suis pour la paix, mais quand je parle, eux sont pour la guerre ; Dieu envoie Ézéchiel : qu'ils écoutent ou non.","Comment raconterais-je en trois minutes ce que Jésus a fait pour moi ?"],
[12,11,19,140,44,23,"Prends courage","Un complot se trame pour tuer Paul, son neveu l'apprend, et la nuit, le Seigneur dit à Paul : prends courage ; garde-moi des hommes violents qui préparent le mal ; le petit Joas est caché pendant qu'Athalie complote.","Où ai-je besoin d'entendre « prends courage » ?"],
[15,4,19,7,44,24,"Une conscience pure","Accusé devant le gouverneur Félix, Paul déclare : je m'efforce d'avoir une conscience pure devant Dieu et devant les hommes ; Félix, troublé, remet à plus tard ; rends-moi justice, ô Dieu ; les ennemis accusaient les bâtisseurs auprès du roi.","Qu'est-ce que je remets à plus tard dans ma relation avec Dieu ?"],
[17,4,19,58,44,25,"J'en appelle à César","Pour échapper à un procès truqué, Paul en appelle à César : il témoignera devant les grands ; juges, rendez-vous vraiment la justice ? ; Esther se présente devant le roi pour sauver son peuple.","Devant qui Dieu pourrait-il m'envoyer témoigner ?"],
[9,7,20,28,44,26,"Je n'ai pas résisté à la vision","Devant le roi Agrippa, Paul raconte sa conversion : grâce au secours de Dieu, j'ai tenu jusqu'à ce jour ; Agrippa répond : encore un peu, et tu me persuades ; celui qui avoue ses fautes obtient miséricorde ; Samuel dresse une pierre : jusqu'ici l'Éternel nous a secourus.","Où puis-je dire « jusqu'ici, Dieu m'a secouru » ?"],
[1,7,18,37,44,27,"Dans la tempête","Pendant quatorze jours de tempête, tout espoir semble perdu, et Paul se lève : prenez courage, j'ai confiance en Dieu ; Élihou décrit Dieu qui commande au vent et à l'orage ; Noé et les siens sont gardés dans l'arche au milieu du déluge.","Qui puis-je encourager au milieu de sa tempête ?"],
[6,3,18,38,44,27,"Tous arrivèrent sains et saufs","Paul rompt le pain au milieu de la tempête, le bateau se brise, et tous arrivent à terre sains et saufs ; Dieu répond à Job du milieu de la tempête : qui a fixé ses limites à la mer ? ; tout Israël traverse le Jourdain à pied sec.","Est-ce que je crois que Dieu tient ses promesses jusqu'au bout ?"],
[23,60,19,54,44,28,"Sans aucun obstacle","À Malte, Paul secoue une vipère sans mal, puis arrive à Rome où, prisonnier dans sa maison, il annonce le Royaume avec assurance et sans obstacle ; Dieu est mon secours ; Ésaïe : les nations marcheront à ta lumière.","Comment ma situation, même limitée, peut-elle servir l'Évangile ?"],
[35,2,20,30,45,1,"Je n'ai pas honte de l'Évangile","Paul : je n'ai pas honte de l'Évangile, c'est la puissance de Dieu pour sauver quiconque croit, car le juste vivra par la foi ; toute parole de Dieu est éprouvée ; Habacuc : le juste vivra par sa foi.","Ai-je parfois honte de l'Évangile ?"],
[24,2,19,14,45,1,"Échanger la gloire de Dieu","Ce qu'on peut connaître de Dieu se voit dans la création, mais les hommes ont échangé sa gloire contre des images ; l'insensé dit dans son cœur : il n'y a pas de Dieu ; Jérémie : mon peuple a échangé sa gloire contre ce qui ne sert à rien.","Qu'est-ce que j'adore à la place de Dieu, sans m'en rendre compte ?"],
[24,4,19,52,45,2,"Toi qui juges","Paul interpelle celui qui juge les autres : tu fais les mêmes choses, et la bonté de Dieu te pousse à changer ; le psaume dénonce celui qui se croit fort dans le mal ; Jérémie : purifiez votre cœur pour l'Éternel.","Qui suis-je prompt à juger, alors que je fais pareil ?"],
[23,59,19,53,45,3,"Tous ont péché","Il n'y a pas de juste, pas même un seul : tous ont péché et sont privés de la gloire de Dieu ; Dieu regarde du ciel : il n'y en a aucun qui fasse le bien ; Ésaïe : ce sont vos fautes qui vous séparent de votre Dieu.","Est-ce que je me crois meilleur que d'autres devant Dieu ?"],
[3,17,21,7,45,3,"Justifiés gratuitement","Nous sommes justifiés gratuitement par sa grâce, par Jésus, que Dieu a présenté comme le lieu du pardon ; il n'y a sur terre aucun juste qui ne pèche jamais ; la loi disait : la vie est dans le sang, c'est lui qui fait l'expiation.","Est-ce que je vis ma relation avec Dieu comme un cadeau ou comme un salaire ?"],
[1,17,20,16,45,4,"La foi d'Abraham","Abraham crut Dieu, et cela lui fut compté comme justice, avant même la circoncision : il est le père de tous ceux qui croient ; par la bonté et la fidélité la faute est pardonnée ; Dieu change le nom d'Abram en Abraham, père d'une multitude.","Ma relation avec Dieu repose-t-elle sur la foi ou sur mes mérites ?"],
[1,21,18,11,45,4,"Espérer contre toute espérance","Abraham, malgré son âge, espère contre toute espérance, pleinement persuadé que Dieu peut accomplir sa promesse ; Tsophar : tu auras confiance, car il y a de l'espérance ; Isaac naît, et Sara rit de joie.","Quelle promesse de Dieu me paraît impossible aujourd'hui ?"],
[23,54,18,5,45,5,"La paix avec Dieu","Justifiés par la foi, nous avons la paix avec Dieu, et même l'épreuve produit l'espérance, car Christ est mort pour nous quand nous étions encore pécheurs ; Job : Dieu fait la blessure, et il la panse ; Ésaïe : mon amour ne s'éloignera pas de toi.","Est-ce que je crois que Dieu m'a aimé avant que je change ?"],
[1,4,18,25,45,5,"Là où le péché abonde","Par un seul homme, Adam, le péché est entré dans le monde ; par un seul, Jésus, la grâce a surabondé ; Bildad : comment l'homme serait-il juste devant Dieu ? ; dès Caïn, le péché se tient à la porte et s'étend.","Est-ce que je crois que la grâce de Dieu est plus grande que mon péché ?"],
[2,15,19,142,45,6,"Une vie nouvelle","Baptisés en Christ, nous sommes morts au péché pour marcher dans une vie nouvelle ; tire mon âme de sa prison, afin que je loue ton nom ; Israël, sorti de la mer, chante sa délivrance.","De quelle « prison » Christ m'a-t-il déjà sorti ?"],
[5,11,20,13,45,6,"Le salaire et le don","Vous étiez esclaves du péché, vous voici serviteurs de la justice : le salaire du péché, c'est la mort, mais le don de Dieu, c'est la vie éternelle ; celui qui respecte le commandement en sera récompensé ; Moïse place devant le peuple la bénédiction et la malédiction.","À quoi est-ce que je me donne chaque jour ?"],
[5,5,18,31,45,7,"Tu ne convoiteras pas","La loi est sainte, mais en disant « tu ne convoiteras pas », elle m'a fait découvrir le péché qui était en moi ; Job avait fait un pacte avec ses yeux ; Moïse redit les dix paroles au peuple.","Quelle convoitise la Parole de Dieu met-elle en lumière chez moi ?"],
[7,16,20,26,45,7,"Le combat intérieur","Je ne fais pas le bien que je veux, et je fais le mal que je ne veux pas : qui me délivrera ? Grâce soit rendue à Dieu par Jésus-Christ ; comme le chien retourne à ce qu'il a vomi, l'insensé revient à sa folie ; Samson, si fort, reste esclave de ses faiblesses.","Dans quel combat ai-je besoin de compter sur Jésus plutôt que sur moi ?"],
[38,3,18,10,45,8,"Aucune condamnation","Il n'y a plus aucune condamnation pour ceux qui sont en Jésus-Christ, et l'Esprit nous fait crier : Abba, Père ; Job suppliait : ne me condamne pas ; Zacharie voit l'accusateur réduit au silence et le prêtre revêtu d'habits propres.","Est-ce que je vis encore sous une condamnation que Jésus a ôtée ?"],
[23,11,21,1,45,8,"La création soupire","La création, soumise à la vanité, attend avec impatience, et nous soupirons avec elle, mais l'Esprit intercède, et tout contribue au bien de ceux qui aiment Dieu ; tout est vanité, dit l'Ecclésiaste ; Ésaïe : le loup habitera avec l'agneau.","Quel soupir puis-je laisser l'Esprit porter devant Dieu ?"],
[28,2,19,59,45,8,"Rien ne nous séparera","Si Dieu est pour nous, qui sera contre nous ? Rien ne pourra nous séparer de l'amour de Dieu manifesté en Jésus ; le Dieu de ma bonté vient au-devant de moi ; Osée : je te fiancerai à moi pour toujours.","Qu'est-ce qui me fait douter de l'amour de Dieu ?"],
[24,18,19,79,45,9,"La miséricorde du potier","Paul a une grande tristesse pour son peuple, puis contemple la liberté de Dieu, qui fait miséricorde comme le potier façonne l'argile ; les nations ont envahi ton héritage, aie pitié de nous ; Jérémie voit le potier refaire un vase.","Est-ce que je laisse Dieu me façonner ?"],
[34,1,19,70,45,10,"La parole est près de toi","Si tu confesses de ta bouche que Jésus est Seigneur et crois dans ton cœur que Dieu l'a ressuscité, tu seras sauvé ; que ceux qui te cherchent soient dans la joie ; Nahum : voici sur les montagnes les pieds du messager de bonnes nouvelles.","Ma foi passe-t-elle du cœur à la bouche ?"],
[12,7,19,48,45,10,"Comment entendront-ils ?","Comment croiront-ils sans avoir entendu, et comment entendront-ils si personne ne leur annonce ? La foi vient de ce qu'on entend ; racontez-le à la génération future ; les lépreux de Samarie : c'est un jour de bonne nouvelle, et nous nous taisons !","Qui, autour de moi, n'a peut-être jamais entendu l'Évangile ?"],
[28,3,19,94,45,11,"L'olivier et les branches","Dieu n'a pas rejeté son peuple ; les nations sont greffées sur l'olivier, et tout Israël sera sauvé : ô profondeur de la sagesse de Dieu ! ; l'Éternel n'abandonne pas son peuple ; Osée : ensuite, les enfants d'Israël reviendront.","Est-ce que je prie pour Israël ?"],
[5,13,19,12,48,1,"Un seul Évangile","Paul s'étonne que les Galates se détournent si vite vers un autre évangile ; les paroles de l'Éternel sont pures ; Moïse : même si un prophète fait un signe, s'il vous éloigne de Dieu, ne l'écoutez pas.","Est-ce que j'ajoute quelque chose à l'Évangile pour me sentir en règle ?"],
[14,19,20,9,48,2,"Reprendre un frère","À Antioche, Pierre cesse de manger avec les croyants non juifs, et Paul le reprend en face, pour la vérité de l'Évangile ; reprends le sage, il t'aimera ; le prophète Jéhu reprend le bon roi Josaphat.","Est-ce que j'accepte d'être repris, ou de reprendre avec amour ?"],
[3,1,22,6,48,2,"Ce n'est plus moi qui vis","J'ai été crucifié avec Christ, ce n'est plus moi qui vis, c'est Christ qui vit en moi ; je suis à mon bien-aimé, et mon bien-aimé est à moi ; l'holocauste était tout entier offert à Dieu.","Qu'est-ce que ça change concrètement que Christ vive en moi ?"],
[5,21,20,10,48,3,"Pendu au bois pour nous","Christ nous a rachetés de la malédiction en devenant malédiction pour nous, afin que la bénédiction d'Abraham arrive aux nations ; c'est la bénédiction de l'Éternel qui enrichit ; la loi disait : maudit celui qui est pendu au bois.","Est-ce que je vis sous la bénédiction ou sous la peur ?"],
[3,25,18,39,48,5,"La liberté","C'est pour la liberté que Christ nous a libérés : ne vous remettez pas sous le joug, mais servez-vous les uns les autres par amour ; Dieu demande à Job : qui a laissé l'âne sauvage en liberté ? ; au jubilé, on proclamait la liberté dans le pays.","Comment j'utilise ma liberté en Christ ?"],
[26,47,20,6,48,5,"Le fruit de l'Esprit","Paul oppose les œuvres de la chair au fruit de l'Esprit : amour, joie, paix, patience, bonté, bienveillance, fidélité, douceur, maîtrise de soi ; les Proverbes énumèrent ce que Dieu déteste ; Ézéchiel voit des arbres qui donnent du fruit chaque mois près du fleuve de Dieu.","Quel fruit de l'Esprit ai-je le plus besoin de voir grandir ?"],
[28,10,21,11,48,6,"Ne nous lassons pas","Portez les fardeaux les uns des autres ; on récolte ce que l'on a semé : ne nous lassons pas de faire le bien ; sème dès le matin, et le soir ne laisse pas reposer ta main ; Osée : semez selon la justice, moissonnez selon la bonté.","Dans quel bien suis-je tenté de me lasser ?"],
[39,1,20,21,45,12,"Un sacrifice vivant","Offrez votre corps comme un sacrifice vivant, et ne vous conformez pas au monde : soyez transformés par le renouvellement de votre intelligence ; pratiquer la justice vaut mieux que les sacrifices ; Malachie : vous m'offrez ce qui est boiteux et malade.","Quelle part de ma vie dois-je offrir à Dieu aujourd'hui ?"],
[9,24,19,109,45,12,"Vaincre le mal par le bien","Que l'amour soit sincère : bénissez ceux qui vous persécutent, ne rendez à personne le mal pour le mal, sois vainqueur du mal par le bien ; on me rend la haine pour mon amour, mais moi je prie ; David épargne Saül qui le poursuit.","Où puis-je répondre au mal par le bien cette semaine ?"],
[24,29,21,8,45,13,"La nuit est avancée","Soyez soumis aux autorités, ne devez rien à personne, sinon de vous aimer ; la nuit est avancée, revêtez-vous du Seigneur Jésus ; observe les ordres du roi ; Jérémie aux exilés : recherchez le bien de la ville où vous êtes.","Comment être chrétien dans ma ville et dans ma société ?"],
[27,1,18,34,45,14,"Ne pas juger son frère","Pour la nourriture et les jours, ne méprisez pas celui qui pense autrement : chacun rendra compte à Dieu, et le royaume, c'est la justice, la paix et la joie ; Élihou : Dieu rend à chacun selon ses œuvres ; Daniel choisissait de ne pas manger les mets du roi.","Sur quel sujet secondaire ai-je tendance à juger les autres ?"],
[1,13,18,4,45,15,"Accueillez-vous","Les forts doivent porter les faiblesses des faibles, sans chercher ce qui leur plaît : accueillez-vous comme Christ vous a accueillis ; Éliphaz rappelle à Job : tes paroles relevaient ceux qui chancelaient ; Abram laisse Lot choisir pour garder la paix.","Qui ai-je besoin d'accueillir comme Christ m'a accueilli ?"],
[16,3,18,29,45,16,"Des noms et des visages","Paul salue des dizaines de personnes : Phœbé, Priscille et Aquilas, des femmes et des hommes qui ont travaillé pour le Seigneur ; Job : j'étais les yeux de l'aveugle et les pieds du boiteux ; Néhémie nomme chacun de ceux qui ont rebâti la muraille.","Qui pourrais-je remercier pour son service ?"],
[5,14,19,144,49,1,"Bénis de toute bénédiction","Béni soit Dieu : il nous a choisis, adoptés, rachetés par le sang de Jésus et marqués du sceau de l'Esprit ; heureux le peuple dont l'Éternel est le Dieu ; Moïse : l'Éternel t'a choisi pour être son peuple.","Laquelle de ces bénédictions ai-je oublié de recevoir ?"],
[27,2,18,28,49,1,"Que les yeux de votre cœur s'ouvrent","Paul prie pour que Dieu ouvre les yeux de notre cœur, afin de connaître l'espérance et la puissance qui a ressuscité Christ ; Job : où trouvera-t-on la sagesse ? Dieu seul en connaît le chemin ; Daniel : c'est Dieu qui révèle ce qui est profond et caché.","Sur quoi ai-je besoin que Dieu m'ouvre les yeux ?"],
[26,16,19,107,49,2,"Sauvés par grâce","Nous étions morts dans nos fautes, mais Dieu, riche en miséricorde, nous a rendus vivants : c'est par grâce que vous êtes sauvés, cela ne vient pas de vous ; qu'ils le disent, ceux que l'Éternel a rachetés ; Ézéchiel : Dieu trouve une enfant abandonnée et lui dit : vis !","Est-ce que je vis comme quelqu'un qui a été sauvé gratuitement ?"],
[23,2,19,87,49,2,"Le mur abattu","Christ est notre paix : de deux peuples, il en a fait un seul en renversant le mur de la haine, et nous devenons ensemble une demeure de Dieu ; de chacun on dira : celui-ci est né à Sion ; Ésaïe : toutes les nations afflueront vers la montagne de l'Éternel.","Quel « mur » reste debout entre moi et quelqu'un d'autre ?"],
[26,3,18,32,49,3,"Le plus petit de tous","Paul, prisonnier, se dit le plus petit de tous, chargé pourtant d'annoncer aux nations les richesses insondables du Christ ; le jeune Élihou : c'est l'Esprit qui donne l'intelligence, et il me presse de parler ; Ézéchiel reçoit le rouleau et part vers son peuple.","Quelle grâce ai-je reçue, que Dieu veut que je partage ?"],
[23,64,18,26,49,3,"Infiniment au-delà","Paul prie pour que nous comprenions la largeur, la longueur, la hauteur et la profondeur de l'amour du Christ, qui dépasse toute connaissance ; Job : ce ne sont là que les bords de ses voies ; Ésaïe : jamais l'œil n'a vu un Dieu qui agisse ainsi pour ceux qui l'attendent.","Est-ce que je mesure l'amour de Dieu à ma petite échelle ?"],
[2,31,19,68,49,4,"Un seul corps, des dons variés","Paul appelle à garder l'unité de l'Esprit : un seul corps, un seul Seigneur, et le Christ ressuscité a fait des dons pour que chacun grandisse ; tu es monté en haut, tu as reçu des dons pour les hommes ; Dieu remplit Betsaleel de son Esprit pour l'ouvrage.","Quel don ai-je reçu pour faire grandir les autres ?"],
[1,33,19,64,49,4,"Le vieil homme et le nouveau","Dépouillez-vous du vieil homme : que votre colère ne dure pas, que vos paroles fassent du bien, pardonnez-vous comme Dieu vous a pardonné ; le psaume dénonce les langues aiguisées comme des épées ; Jacob et Ésaü s'embrassent après des années de rancune.","Quelle parole vais-je éviter aujourd'hui, et laquelle vais-je dire ?"],
[1,29,22,7,49,5,"Comme Christ a aimé l'Église","Marchez dans l'amour ; maris et femmes, soumettez-vous l'un à l'autre : Christ a aimé l'Église et s'est donné pour elle ; je suis à mon bien-aimé, et son désir se porte vers moi ; Jacob servit sept ans pour Rachel, et ils lui parurent quelques jours.","Comment l'amour de Christ peut-il transformer mon couple ou mes relations ?"],
[14,5,21,9,49,5,"Remplis de l'Esprit","Marchez en enfants de lumière, profitez du temps présent, soyez remplis de l'Esprit et chantez au Seigneur de tout votre cœur ; tout ce que ta main trouve à faire, fais-le avec ta force ; quand les chantres louent d'une seule voix, la gloire remplit le temple.","Comment j'utilise le temps que Dieu me donne ?"],
[9,17,19,60,49,6,"Les armes de Dieu","Notre combat n'est pas contre la chair et le sang : prenez la ceinture de vérité, la cuirasse de justice, le bouclier de la foi, l'épée de l'Esprit ; avec Dieu, nous ferons des exploits ; David refuse l'armure de Saül et s'avance au nom de l'Éternel.","Quelle pièce de l'armure de Dieu me manque le plus ?"],
[5,4,20,23,49,6,"En famille et au travail","Enfants, obéissez ; pères, n'exaspérez pas vos enfants ; serviteurs et maîtres, vous avez le même Seigneur ; et priez en tout temps ; que ton père et ta mère se réjouissent ; Moïse : fais connaître ces choses à tes enfants.","Comment ma foi se voit-elle dans ma maison et à mon travail ?"],
[17,8,18,22,51,2,"La dette clouée à la croix","En Christ habite toute la plénitude de Dieu ; il a effacé l'acte écrit contre nous en le clouant à la croix, alors ne laissez personne vous juger sur des règles humaines ; Éliphaz : réconcilie-toi avec Dieu, et tu auras la paix ; un nouveau décret du roi annule celui qui condamnait le peuple.","Quelle « dette » ai-je encore l'impression de devoir payer à Dieu ?"],
[23,33,21,6,51,3,"Les choses d'en haut","Recherchez les choses d'en haut, votre vie est cachée avec Christ en Dieu ; revêtez-vous de compassion, de bonté, d'humilité, et pardonnez ; l'œil n'est jamais rassasié de ce qu'il voit ; Ésaïe : tes yeux contempleront le roi dans sa beauté.","À quoi mes pensées sont-elles le plus attachées ?"],
[2,36,21,10,51,3,"Comme pour le Seigneur","Que la paix de Christ règne dans vos cœurs, que sa parole habite en vous, et tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur ; l'Ecclésiaste : par la paresse, la charpente s'effondre ; les artisans du tabernacle travaillaient avec tout leur savoir-faire.","Quel travail ordinaire puis-je faire aujourd'hui « pour le Seigneur » ?"],
[16,2,20,25,51,4,"Une parole pleine de sel","Persévérez dans la prière, et que votre parole soit toujours aimable, assaisonnée de sel ; une parole dite à propos est comme des pommes d'or ; Néhémie prie en silence avant de répondre au roi.","Comment mes paroles peuvent-elles avoir du goût aujourd'hui ?"],
[24,32,18,27,50,1,"Christ est ma vie","En prison, Paul se réjouit que l'Évangile avance : pour moi, vivre, c'est Christ, et mourir est un gain ; Job : tant que j'aurai un souffle, je garderai mon intégrité ; Jérémie achète un champ en pleine guerre, signe d'avenir.","Pour moi, vivre, c'est… quoi ?"],
[1,19,18,1,50,3,"Tout est perte à côté de Christ","Paul considère tout ce dont il était fier comme une perte, à cause de la valeur suprême de connaître Christ ; Job : l'Éternel a donné, l'Éternel a repris, que son nom soit béni ; la femme de Lot regarde en arrière et s'arrête.","Qu'est-ce que je tiens encore pour un gain, que je devrais lâcher ?"],
[6,14,19,84,50,3,"Je cours vers le but","J'oublie ce qui est derrière, je me porte vers ce qui est devant, et je cours vers le but, car notre cité est dans les cieux ; ils marchent de force en force ; à 85 ans, Caleb réclame encore la montagne promise.","Qu'est-ce que je dois laisser derrière pour avancer ?"],
[35,3,18,8,50,4,"Réjouissez-vous toujours","Réjouissez-vous toujours dans le Seigneur, ne vous inquiétez de rien, et la paix de Dieu gardera vos cœurs ; Bildad : il remplira encore ta bouche de cris de joie ; Habacuc : même si le figuier ne fleurit pas, je me réjouirai en l'Éternel.","Quelle inquiétude vais-je changer en prière aujourd'hui ?"],
[14,31,20,30,50,4,"J'ai appris à être content","J'ai appris à être content dans l'abondance comme dans le manque : je peux tout par celui qui me fortifie, et mon Dieu pourvoira à vos besoins ; ne me donne ni pauvreté ni richesse ; sous Ézéchias, le peuple donne tant que les offrandes s'entassent.","Dans quel domaine ai-je besoin d'apprendre le contentement ?"],
[4,12,18,15,46,1,"Christ est-il divisé ?","À Corinthe, on se divise : moi, je suis de Paul, moi d'Apollos ; Paul demande : Christ est-il divisé ? ; Éliphaz : la sagesse t'appartient-elle à toi seul ? ; Miriam et Aaron critiquent Moïse par jalousie.","Est-ce que je mets un homme ou un groupe au-dessus de Christ ?"],
[7,7,19,147,46,1,"La folie de la croix","La croix paraît folie, mais elle est puissance de Dieu, et Dieu a choisi ce qui est faible pour confondre ce qui est fort ; il ne prend pas plaisir à la force du cheval, mais à ceux qui espèrent en sa bonté ; Dieu réduit l'armée de Gédéon à trois cents hommes.","Où Dieu veut-il agir à travers ma faiblesse ?"],
[5,29,20,20,46,2,"La pensée de Christ","Paul n'est pas venu avec de beaux discours, mais avec la puissance de l'Esprit, qui sonde les profondeurs de Dieu : nous avons la pensée de Christ ; l'esprit de l'homme est une lampe de l'Éternel ; Moïse : les choses cachées sont à Dieu, les choses révélées sont à nous.","Est-ce que je demande à l'Esprit de m'éclairer quand je lis la Bible ?"],
[15,3,19,127,46,3,"Le seul fondement","Paul a planté, Apollos a arrosé, mais Dieu fait croître ; personne ne peut poser un autre fondement que Jésus-Christ, et vous êtes le temple de Dieu ; si l'Éternel ne bâtit la maison… ; au retour d'exil, on pose les fondations du temple avec des cris et des larmes.","Sur quel fondement est-ce que je bâtis ce que je fais pour Dieu ?"],
[4,16,20,27,46,4,"Qu'as-tu que tu n'aies reçu ?","Qu'on nous regarde comme des serviteurs de Christ, à qui l'on demande d'être fidèles : qu'as-tu que tu n'aies reçu ? ; qu'un autre fasse ton éloge, et non ta bouche ; Koré conteste la place de Moïse par orgueil.","De quoi suis-je tenté de me vanter, que j'ai reçu ?"],
[4,25,20,7,46,5,"Un peu de levain","L'Église tolère une immoralité grave, et Paul rappelle : un peu de levain fait lever toute la pâte ; Christ, notre Pâque, a été sacrifié ; les Proverbes décrivent le piège de la séduction ; au désert, le peuple se laisse entraîner à Baal-Peor.","Quel petit « levain » ai-je laissé entrer dans ma vie ?"],
[10,11,18,24,46,6,"Le temple de l'Esprit","Paul reprend les procès entre frères et rappelle : votre corps est le temple du Saint-Esprit, fuyez l'impureté et glorifiez Dieu dans votre corps ; Job décrit l'adultère qui attend le crépuscule en pensant que nul ne le voit ; David, oisif, tombe avec Bath-Shéba.","Comment honorer Dieu dans mon corps ?"],
[24,16,20,18,46,7,"Mariage et célibat","Paul parle du couple, de la fidélité et du célibat : chacun a reçu de Dieu son don particulier ; celui qui trouve une épouse trouve le bonheur ; Dieu demande à Jérémie de rester célibataire, comme un signe.","Comment ma situation actuelle peut-elle servir le Seigneur ?"],
[5,22,20,3,46,8,"La connaissance et l'amour","La connaissance rend orgueilleux, l'amour construit : attention que ta liberté ne fasse pas tomber un frère plus fragile ; ne sois pas sage à tes propres yeux ; la loi demandait un parapet sur le toit pour protéger les autres.","Est-ce que ma liberté pourrait faire tomber quelqu'un ?"],
[16,5,21,9,46,9,"Tout à tous","Paul renonce à ses droits pour ne pas gêner l'Évangile, se fait tout à tous et court pour remporter le prix, en maîtrisant son corps ; la course n'est pas aux plus rapides ; Néhémie refuse le salaire du gouverneur pour ne pas charger le peuple.","À quel droit pourrais-je renoncer pour que l'Évangile avance ?"],
[4,14,19,78,46,10,"Des exemples pour nous","Les Israélites au désert ont tous été nourris par Dieu, et pourtant beaucoup sont tombés : que celui qui croit être debout prenne garde ; Dieu ne permettra pas que vous soyez tentés au-delà de vos forces ; le psaume raconte leurs révoltes ; le peuple refuse d'entrer dans le pays.","Quelle tentation dois-je affronter avec la porte de sortie que Dieu me donne ?"],
[3,7,19,116,46,11,"En mémoire de moi","Paul transmet ce qu'il a reçu : le Seigneur Jésus, la nuit où il fut livré, prit du pain… ; que chacun s'examine avant de manger ; j'élèverai la coupe du salut ; la loi interdisait de manger le repas de communion en étant impur.","Comment me préparer avant de prendre la cène ?"],
[2,35,19,104,46,12,"Des dons variés, un même Esprit","Il y a diversité de dons et de services, mais c'est le même Esprit qui donne à chacun pour le bien de tous ; que tes œuvres sont nombreuses, tu les as toutes faites avec sagesse ; pour le tabernacle, chacun apporte ce que son cœur et son talent permettent.","Quel don l'Esprit m'a-t-il donné pour les autres ?"],
[16,4,19,133,46,12,"Beaucoup de membres","L'œil ne peut pas dire à la main : je n'ai pas besoin de toi ; les membres qui paraissent faibles sont nécessaires, et si l'un souffre, tous souffrent ; qu'il est doux pour des frères de vivre unis ; sur la muraille, chacun tenait sa place, la truelle d'une main et l'épée de l'autre.","Qui, dans mon Église, a besoin que je le reconnaisse ?"],
[28,14,22,8,46,13,"L'amour est patient","Sans l'amour, je ne suis rien : l'amour est patient, il est plein de bonté, il ne cherche pas son intérêt, il excuse tout, il espère tout ; l'amour est fort comme la mort ; Osée : je les aimerai de bon cœur.","Quel trait de l'amour me manque le plus ?"],
[10,19,20,10,46,13,"L'amour ne passera jamais","Aujourd'hui nous voyons comme dans un miroir, demain face à face ; la foi, l'espérance et l'amour demeurent, mais le plus grand, c'est l'amour ; l'amour couvre toutes les fautes ; revenu au pouvoir, David pardonne à Schimeï qui l'avait maudit.","Où mon amour doit-il « couvrir » une faute aujourd'hui ?"],
[13,25,19,111,46,14,"Que tout serve à bâtir","Paul encourage à rechercher les dons qui bâtissent l'Église, et à tout faire avec ordre et intelligence ; je louerai l'Éternel de tout mon cœur dans l'assemblée ; David établit des musiciens qui prophétisaient avec la harpe.","Qu'est-ce que j'apporte au culte pour bâtir les autres ?"],
[15,8,19,27,46,16,"Veillez, soyez forts","Paul organise la collecte pour les pauvres et conclut : veillez, tenez ferme dans la foi, soyez forts, et que tout se fasse avec amour ; fortifie-toi, que ton cœur s'affermisse ; Esdras confie l'or des offrandes à des hommes intègres pour le voyage.","Dans quel domaine ai-je besoin d'être fort, avec amour ?"],
[23,51,19,94,47,1,"Le Dieu de toute consolation","Dieu nous console dans toutes nos détresses, afin que nous puissions consoler les autres ; quand les pensées s'agitent en moi, tes consolations réjouissent mon âme ; Ésaïe : c'est moi, c'est moi qui vous console.","Qui pourrais-je consoler avec la consolation que j'ai reçue ?"],
[3,2,18,6,47,2,"La bonne odeur de Christ","Paul demande de pardonner et de réconforter celui qui a fauté, pour qu'il ne soit pas accablé ; nous sommes pour Dieu la bonne odeur de Christ ; Job : celui qui souffre a droit à la compassion de son ami ; l'offrande était une odeur agréable à l'Éternel.","Qui a besoin que je le relève plutôt que de l'accabler ?"],
[26,11,19,34,47,3,"Le visage découvert","Vous êtes une lettre écrite par l'Esprit sur des cœurs de chair ; le visage découvert, nous contemplons la gloire du Seigneur et sommes transformés ; ceux qui le regardent sont rayonnants ; Ézéchiel : j'ôterai le cœur de pierre et vous donnerai un cœur de chair.","Qu'est-ce que Dieu est en train de transformer en moi, peu à peu ?"],
[25,3,18,30,47,4,"Un trésor dans des vases de terre","Nous portons ce trésor dans des vases de terre : pressés de toutes parts, mais pas écrasés, abattus, mais pas détruits ; Job crie sa souffrance sans cacher sa fragilité ; au cœur du malheur, le prophète se souvient : les bontés de l'Éternel se renouvellent chaque matin.","Où ma fragilité laisse-t-elle voir la force de Dieu ?"],
[1,47,18,7,47,4,"Ce qui ne se voit pas","Même si notre corps s'use, l'homme intérieur se renouvelle de jour en jour, et nos détresses préparent une gloire éternelle ; Job : ma vie n'est qu'un souffle ; Jacob parle à Pharaon de ses années de pèlerinage.","Sur quoi mes yeux sont-ils fixés : ce qui se voit, ou ce qui ne se voit pas ?"],
[4,33,19,16,47,5,"Nous marchons par la foi","Notre tente terrestre sera détruite, mais nous avons une demeure éternelle : nous marchons par la foi, non par la vue ; tu me fais connaître le chemin de la vie ; Moïse note chaque étape du voyage d'Israël vers la promesse.","Dans quelle situation ai-je besoin de marcher par la foi plutôt que par la vue ?"],
[10,14,19,32,47,5,"Ambassadeurs de la réconciliation","Si quelqu'un est en Christ, il est une nouvelle création : Dieu nous a réconciliés et nous confie le message de la réconciliation ; heureux celui dont la faute est pardonnée ; une femme sage rappelle à David que Dieu cherche le moyen de ramener le banni.","Avec qui suis-je appelé à vivre la réconciliation ?"],
[3,26,19,69,47,6,"Voici le temps favorable","Voici maintenant le temps favorable, voici le jour du salut ; ne vous associez pas à ce qui éloigne de Dieu, car vous êtes le temple du Dieu vivant ; au temps favorable, ô Dieu, réponds-moi ; la loi : je marcherai au milieu de vous, je serai votre Dieu.","Qu'est-ce que je remets à demain, que Dieu me demande aujourd'hui ?"],
[15,10,18,42,47,7,"La tristesse selon Dieu","Paul se réjouit que sa lettre ait attristé les Corinthiens, car la tristesse selon Dieu produit un vrai changement ; Job : je me repens sur la poussière et la cendre ; au temps d'Esdras, le peuple pleure et revient à Dieu.","Ma tristesse face au péché me conduit-elle à changer ?"],
[5,24,20,11,47,8,"Riche, il s'est fait pauvre","Les Églises de Macédoine, très pauvres, ont donné avec joie au-delà de leurs moyens, car Jésus, qui était riche, s'est fait pauvre pour nous ; celui qui arrose sera lui-même arrosé ; la loi laissait au pauvre ce qui restait dans les champs.","Comment ma générosité reflète-t-elle celle de Jésus ?"],
[5,16,19,112,47,9,"Dieu aime celui qui donne avec joie","Celui qui sème peu moissonnera peu, celui qui sème largement moissonnera largement : Dieu aime celui qui donne avec joie ; l'homme juste distribue, il donne aux pauvres ; Moïse : chacun donnera selon la bénédiction reçue.","Est-ce que je donne avec joie, ou par obligation ?"],
[6,6,19,76,47,10,"Les forteresses renversées","Nos armes ne sont pas humaines : elles renversent les forteresses et soumettent toute pensée à Christ ; là, Dieu a brisé les flèches, le bouclier et l'épée ; les murs de Jéricho tombent au cri de la foi.","Quelle pensée dois-je soumettre à Christ ?"],
[26,13,18,20,47,11,"Fiancés à un seul époux","Paul est jaloux pour l'Église qu'il a fiancée à Christ, il démasque les faux apôtres et énumère ses souffrances, et le souci de toutes les Églises ; Tsophar : le triomphe des méchants est de courte durée ; Ézéchiel dénonce les faux prophètes qui recouvrent un mur fragile.","Qu'est-ce qui pourrait détourner mon cœur de la simplicité envers Christ ?"],
[2,4,18,3,47,12,"Ma grâce te suffit","Paul a reçu une écharde dans la chair et a prié trois fois pour qu'elle parte ; le Seigneur répond : ma grâce te suffit, ma puissance s'accomplit dans la faiblesse ; Job ose dire toute sa détresse ; Moïse se trouve incapable de parler, et Dieu répond : qui a fait la bouche de l'homme ?","Quelle faiblesse dois-je cesser de cacher pour que la grâce y agisse ?"],
[14,14,19,46,47,12,"Quand je suis faible, je suis fort","Paul se glorifie de ses faiblesses : quand je suis faible, c'est alors que je suis fort ; il ne cherche pas leurs biens, mais eux-mêmes ; Dieu est notre force, un secours toujours présent ; le roi Asa prie : toi seul peux secourir le faible comme le fort.","Est-ce que j'ose venir à Dieu avec ma faiblesse ?"],
[37,1,19,26,47,13,"Examinez-vous","Paul invite à s'examiner : êtes-vous dans la foi ? puis il bénit : la grâce du Seigneur Jésus, l'amour de Dieu et la communion du Saint-Esprit soient avec vous ; éprouve-moi, Éternel, sonde-moi ; Aggée : réfléchissez à votre conduite.","Si je m'examine honnêtement, où en est ma foi ?"],
[14,33,19,130,54,1,"Le premier des pécheurs","Paul s'émerveille : moi, autrefois violent et persécuteur, j'ai obtenu miséricorde, car Christ est venu sauver les pécheurs, dont je suis le premier ; si tu gardais le compte des fautes, qui tiendrait debout ? ; Manassé, le pire des rois, s'humilie, et Dieu l'exauce.","Est-ce que je crois que la miséricorde de Dieu est plus grande que mon passé ?"],
[26,22,19,20,54,2,"Prier pour tous","Paul demande de prier pour tous, y compris les dirigeants, car Dieu veut que tous soient sauvés, et il n'y a qu'un seul médiateur, Jésus-Christ ; que l'Éternel te réponde au jour de la détresse ; Dieu cherche un homme qui se tienne à la brèche.","Pour quel dirigeant vais-je prier aujourd'hui ?"],
[4,27,19,101,54,3,"Des responsables selon Dieu","Paul décrit ceux qui conduisent l'Église : irréprochables, sobres, accueillants, doux, bons dans leur famille ; mes yeux seront sur les fidèles du pays ; Moïse demande à Dieu un berger pour le peuple, et Josué est désigné.","Ma vie privée est-elle en accord avec ma foi ?"],
[14,34,19,1,54,4,"Exerce-toi à la piété","Paul encourage Timothée : que personne ne méprise ta jeunesse, sois un modèle, exerce-toi à la piété, elle est utile à tout ; heureux l'homme qui médite la loi jour et nuit ; Josias, encore jeune, commence à chercher Dieu.","Quel exercice spirituel vais-je pratiquer cette semaine ?"],
[8,3,19,146,54,5,"Prendre soin des siens","Paul demande d'honorer les veuves, de prendre soin de sa propre famille et de respecter les anciens ; l'Éternel soutient l'orphelin et la veuve ; Ruth prend soin de Noémi, et Boaz étend sur elle sa protection.","Quel membre de ma famille a besoin de mon soin ?"],
[11,21,21,5,54,6,"La piété avec le contentement","C'est un grand gain que la piété avec le contentement, car nous n'avons rien apporté dans le monde ; l'amour de l'argent est une racine de toutes sortes de maux ; tel il est sorti du ventre de sa mère, il s'en va nu ; Achab convoite la vigne de Naboth jusqu'au crime.","Qu'est-ce qui suffirait vraiment à mon bonheur ?"],
[11,10,19,62,54,6,"Combats le bon combat","Poursuis la justice, la foi, l'amour, combats le bon combat ; que les riches ne placent pas leur espérance dans l'argent, mais en Dieu, et soient riches en bonnes œuvres ; si les richesses augmentent, n'y attachez pas votre cœur ; la reine de Saba s'émerveille des richesses de Salomon.","Où ai-je placé mon espérance ?"],
[2,2,19,71,55,1,"La foi transmise","Paul se souvient de la foi sincère de Timothée, qui habitait d'abord sa grand-mère et sa mère : ravive le don de Dieu, car il ne nous a pas donné un esprit de peur ; dès ma jeunesse, tu m'as instruit ; la mère de Moïse le cache et l'élève au milieu de son peuple.","De qui ai-je reçu la foi, et à qui vais-je la transmettre ?"],
[15,7,20,22,55,2,"Un ouvrier qui n'a pas à rougir","Comme un soldat, un athlète, un cultivateur, persévère ; efforce-toi d'être un ouvrier qui enseigne correctement la parole de vérité ; vois-tu un homme habile dans son ouvrage ? ; Esdras avait appliqué son cœur à étudier, pratiquer et enseigner la loi.","Comment je travaille la Parole pour la transmettre ?"],
[7,21,19,10,55,3,"Des temps difficiles","Paul annonce des derniers jours difficiles : des hommes égoïstes, amis de l'argent, qui ont l'apparence de la piété sans sa force ; le méchant dit dans son cœur : Dieu oublie ; à la fin des Juges, chacun faisait ce qui lui semblait bon.","Ma piété a-t-elle la force de Dieu, ou seulement l'apparence ?"],
[5,31,19,19,55,3,"Toute Écriture est inspirée","Depuis ton enfance, tu connais les saintes Écritures : toute Écriture est inspirée de Dieu et utile pour enseigner, convaincre, corriger, former ; la loi de l'Éternel est parfaite, elle restaure l'âme ; Moïse demande qu'on lise la loi devant tout le peuple, enfants compris.","Quelle place la Bible a-t-elle dans mes journées ?"],
[5,34,19,31,55,4,"J'ai gardé la foi","Paul, près de mourir, écrit : j'ai combattu le bon combat, j'ai achevé la course, j'ai gardé la foi ; abandonné de plusieurs, il ajoute : le Seigneur m'a assisté ; entre tes mains, je remets mon esprit ; Moïse meurt après avoir vu de loin le pays promis.","Comment j'aimerais finir ma course ?"],
[16,7,20,20,56,1,"Des hommes fidèles","Paul charge Tite d'établir des responsables irréprochables, attachés à la parole digne de confiance ; beaucoup vantent leur bonté, mais qui trouvera un homme fidèle ? ; Néhémie confie Jérusalem à Hanani, un homme fidèle qui craignait Dieu.","Est-ce qu'on peut compter sur moi ?"],
[7,4,20,31,56,2,"La grâce qui éduque","Paul encourage chaque génération à s'instruire l'une l'autre, car la grâce de Dieu nous enseigne à vivre avec sagesse, justice et piété ; la femme de valeur ouvre la bouche avec sagesse ; Débora conduit Israël et encourage Barak.","Qui puis-je encourager dans une autre génération que la mienne ?"],
[2,40,19,51,56,3,"Le bain de la nouvelle naissance","Dieu nous a sauvés non à cause de nos œuvres, mais par sa miséricorde, par le bain de la nouvelle naissance et le renouvellement du Saint-Esprit ; lave-moi complètement ; au tabernacle, les prêtres se lavaient avant de servir.","Est-ce que je fais le bien pour être sauvé, ou parce que je suis sauvé ?"],
[2,21,20,17,57,1,"Plus qu'un esclave, un frère","Paul renvoie l'esclave Onésime à son maître Philémon : reçois-le comme moi-même, non plus comme un esclave, mais comme un frère bien-aimé ; un frère se montre dans le malheur ; la loi encadrait la condition des esclaves et les protégeait.","Qui ai-je besoin de regarder comme un frère plutôt que selon son statut ?"],
[23,8,19,8,58,2,"Il est devenu notre frère","Jésus a été abaissé un peu au-dessous des anges, il a goûté la mort pour tous, et il n'a pas honte de nous appeler ses frères ; qu'est-ce que l'homme pour que tu penses à lui ? ; Ésaïe : me voici, moi et les enfants que l'Éternel m'a donnés.","Qu'est-ce que ça change que Jésus m'appelle son frère, sa sœur ?"],
[4,13,19,95,58,3,"Aujourd'hui, si vous entendez sa voix","Jésus est plus grand que Moïse ; encouragez-vous chaque jour, tant qu'on peut dire « aujourd'hui », pour que personne ne s'endurcisse ; le psaume répète : n'endurcissez pas votre cœur ; les espions voient des géants et oublient la promesse.","Qui pourrais-je encourager aujourd'hui ?"],
[6,21,19,116,58,4,"Le repos et la Parole","Il reste un repos pour le peuple de Dieu : entrons-y ; la parole de Dieu est vivante, plus tranchante qu'une épée ; mon âme, retourne à ton repos ; Dieu donna du repos à Israël, et aucune de ses promesses ne manqua.","Quelle parole de Dieu a récemment touché juste en moi ?"],
[2,28,19,103,58,4,"Le trône de la grâce","Nous avons un grand prêtre qui compatit à nos faiblesses, tenté comme nous sans pécher : approchons-nous avec assurance du trône de la grâce ; il sait de quoi nous sommes faits ; Aaron portait sur son cœur les noms des tribus d'Israël.","Qu'est-ce que je vais apporter avec assurance au trône de la grâce ?"],
[1,14,19,110,58,5,"Le lait et la nourriture solide","Jésus a appris l'obéissance par ce qu'il a souffert ; les lecteurs, eux, en sont encore au lait au lieu de la nourriture solide ; tu es prêtre pour toujours, à la manière de Melchisédek ; Abram rencontre Melchisédek, roi et prêtre.","Est-ce que je grandis dans la foi, ou est-ce que je reste « au lait » ?"],
[1,9,19,105,58,6,"Une ancre pour l'âme","Allons vers la maturité ; Dieu n'oublie pas votre amour, et sa promesse, confirmée par un serment, est pour nous comme une ancre sûre ; il se souvient pour toujours de son alliance ; après le déluge, Dieu pose son arc dans les nuées.","À quelle promesse de Dieu vais-je ancrer mon âme cette semaine ?"],
[4,17,19,99,58,7,"Toujours vivant pour intercéder","Jésus est prêtre pour toujours : il peut sauver parfaitement ceux qui s'approchent de Dieu par lui, car il est toujours vivant pour intercéder ; Moïse et Aaron invoquaient l'Éternel, et il leur répondait ; le bâton d'Aaron fleurit pour montrer que Dieu l'avait choisi.","Est-ce que je sais que Jésus prie pour moi en ce moment ?"],
[24,31,19,40,58,8,"La nouvelle alliance","Jésus est le médiateur d'une alliance meilleure : je mettrai mes lois dans leur cœur, je pardonnerai leurs fautes ; ta loi est au fond de mon cœur ; Jérémie annonçait cette nouvelle alliance.","Est-ce que j'obéis par contrainte, ou parce que la loi est dans mon cœur ?"],
[3,8,19,24,58,9,"Une fois pour toutes","Le grand prêtre entrait chaque année dans le lieu très saint avec le sang des animaux ; Christ y est entré une fois pour toutes avec son propre sang ; qui montera à la montagne de l'Éternel ? ; Moïse consacrait les prêtres avec le sang.","Est-ce que je vis comme quelqu'un de purifié une fois pour toutes ?"],
[3,4,19,40,58,10,"Me voici pour faire ta volonté","Les sacrifices répétés ne pouvaient ôter les péchés, mais Christ dit : me voici pour faire ta volonté, et par une seule offrande il nous a rendus parfaits ; tu ne voulais ni sacrifice ni offrande, alors j'ai dit : me voici ; la loi demandait sans cesse des sacrifices pour le péché.","Est-ce que j'essaie encore de « payer » pour mes fautes ?"],
[16,10,19,122,58,10,"N'abandonnons pas nos assemblées","Approchons-nous avec un cœur sincère, retenons notre espérance, veillons les uns sur les autres et n'abandonnons pas nos assemblées ; je suis dans la joie quand on me dit : allons à la maison de l'Éternel ; le peuple s'engage : nous ne négligerons pas la maison de notre Dieu.","Quelle place a l'Église dans ma vie ?"],
[1,26,19,105,58,11,"Par la foi","La foi est l'assurance de ce qu'on espère : par la foi, Abel, Hénoc, Noé, Abraham et Sara ont marché vers une patrie qu'ils voyaient de loin ; il se souvient de la parole donnée à Abraham ; Isaac vit en étranger sous la tente et creuse ses puits.","Qu'est-ce que j'espère sans le voir encore ?"],
[6,2,18,21,58,11,"Choisir l'opprobre de Christ","Par la foi, Moïse préfère être maltraité avec le peuple de Dieu plutôt que de jouir du péché pour un temps, et Rahab accueille les espions ; Job s'étonne de la prospérité des méchants ; Rahab cache les espions parce qu'elle croit que l'Éternel est Dieu.","Quel plaisir passager suis-je prêt à refuser par fidélité ?"],
[9,22,19,74,58,11,"Sans avoir vu la promesse","Par la foi, certains ont fermé la gueule des lions, d'autres ont été maltraités sans renier : ils sont morts sans avoir vu la promesse, et le monde n'était pas digne d'eux ; pourquoi, ô Dieu, nous rejettes-tu pour toujours ? ; David et ses compagnons vivent cachés dans la grotte d'Adoullam.","Ma foi tient-elle même quand Dieu ne répond pas comme je le voudrais ?"],
[24,30,20,3,58,12,"Les yeux fixés sur Jésus","Entourés d'une foule de témoins, courons avec persévérance, les yeux fixés sur Jésus ; ne méprisez pas la correction du Seigneur, il corrige ceux qu'il aime ; le Proverbe disait déjà la même chose ; Jérémie : je te corrigerai avec justice, et je te guérirai.","Qu'est-ce qui détourne mes yeux de Jésus dans ma course ?"],
[37,2,18,41,58,12,"Un royaume inébranlable","Vous n'êtes pas venus à une montagne en feu, mais à la Jérusalem céleste : recevant un royaume inébranlable, servons Dieu avec respect, car notre Dieu est un feu dévorant ; Dieu montre à Job la puissance du Léviathan : qui pourrait tenir devant moi ? ; Aggée : j'ébranlerai encore une fois le ciel et la terre.","Qu'est-ce qui, dans ma vie, est bâti sur ce qui ne peut pas être ébranlé ?"],
[13,28,19,118,58,13,"Je ne t'abandonnerai pas","Pratiquez l'hospitalité, souvenez-vous des prisonniers, honorez le mariage, et soyez contents, car Dieu a dit : je ne t'abandonnerai pas ; l'Éternel est pour moi, je ne crains rien ; David à Salomon : l'Éternel ne t'abandonnera pas.","Qu'est-ce qui m'aide à me contenter de ce que j'ai ?"],
[4,19,19,102,58,13,"Le même hier, aujourd'hui, éternellement","Jésus-Christ est le même hier, aujourd'hui et pour toujours ; sortons vers lui hors du camp, en portant son opprobre, et offrons à Dieu un sacrifice de louange ; toi, tu restes le même ; la loi faisait brûler la génisse hors du camp.","Qu'est-ce qui me rassure dans le fait que Jésus ne change pas ?"],
[38,13,18,23,59,1,"La joie dans l'épreuve","Considérez comme un sujet de joie les épreuves, car elles produisent la persévérance ; et si quelqu'un manque de sagesse, qu'il la demande à Dieu ; Job : quand il m'aura éprouvé, je sortirai pur comme l'or ; Zacharie : je les purifierai comme on purifie l'argent.","Qu'est-ce que l'épreuve actuelle peut faire grandir en moi ?"],
[38,7,20,10,59,1,"Mettre la Parole en pratique","Soyez prompts à écouter, lents à parler, lents à vous mettre en colère, et mettez la Parole en pratique ; la vraie religion, c'est visiter les orphelins et les veuves ; celui qui retient ses lèvres est sage ; Zacharie : ne maltraitez ni la veuve, ni l'orphelin, ni l'étranger.","Quelle parole entendue récemment vais-je mettre en pratique ?"],
[33,6,20,22,59,2,"La foi qui agit","Ne faites pas de favoritisme entre riche et pauvre ; la foi sans les œuvres est morte, comme le montrent Abraham et Rahab ; le riche et le pauvre se rencontrent, c'est l'Éternel qui les a faits tous deux ; Michée : pratiquer la justice, aimer la bonté.","Comment ma foi se voit-elle dans mes actes ?"],
[10,16,19,39,59,3,"La langue","La langue est petite, mais comme une étincelle elle enflamme une forêt ; la sagesse d'en haut est pure, pacifique, douce ; je veillerai sur ma bouche ; Schimeï maudit David et lui jette des pierres.","Quelle parole m'a échappé, que je dois réparer ?"],
[23,14,20,27,59,4,"Si le Seigneur le veut","D'où viennent les disputes ? de vos désirs ; humiliez-vous devant le Seigneur, et dites : si le Seigneur le veut, nous vivrons et nous ferons ceci ou cela ; ne te vante pas du lendemain ; Ésaïe : celui qui disait « je monterai au ciel » est précipité.","Mes projets laissent-ils de la place à la volonté de Dieu ?"],
[24,22,19,65,59,5,"La prière fervente","Jacques dénonce ceux qui retiennent le salaire des ouvriers, appelle à la patience du cultivateur, et rappelle qu'Élie pria et que la pluie revint ; tu visites la terre et lui donnes l'abondance ; Jérémie : malheur à celui qui fait travailler son prochain sans le payer.","Pour quoi, ou pour qui, vais-je prier avec ferveur ?"],
[23,48,19,66,60,1,"Plus précieuse que l'or","Béni soit Dieu : il nous a fait naître pour une espérance vivante et un héritage qui ne se flétrit pas, et notre foi éprouvée est plus précieuse que l'or ; tu nous as éprouvés comme on purifie l'argent ; Ésaïe : je t'ai éprouvé au creuset du malheur.","Qu'est-ce que l'épreuve est en train de purifier en moi ?"],
[3,20,19,103,60,1,"Soyez saints","Soyez saints dans toute votre conduite, car vous avez été rachetés par le sang précieux de Christ, et la parole du Seigneur demeure pour toujours ; l'homme est comme l'herbe, mais la bonté de l'Éternel dure toujours ; la loi : soyez saints, car je suis saint.","Quel domaine de ma vie Dieu veut-il rendre saint ?"],
[11,6,19,118,60,2,"Des pierres vivantes","Approchez-vous de Jésus, la pierre vivante rejetée par les hommes, et soyez bâtis en maison spirituelle : vous êtes un peuple choisi, des prêtres au service du roi ; la pierre rejetée est devenue la pierre angulaire ; le temple de Salomon fut bâti avec des pierres taillées à l'avance, sans bruit de marteau.","Quelle est ma place dans la maison que Dieu construit ?"],
[24,50,19,119,60,2,"Revenus au berger","Comme des étrangers, vivez une vie belle au milieu des autres ; Christ a souffert pour vous, vous laissant un exemple, et vous êtes revenus au berger de vos âmes ; je suis errant comme une brebis perdue, cherche ton serviteur ; Jérémie : mon peuple était un troupeau de brebis perdues.","Où ai-je besoin de revenir au berger ?"],
[17,5,19,34,60,3,"Toujours prêts à répondre","Que votre parure soit celle d'un cœur doux et paisible ; ne rendez pas le mal pour le mal, et soyez toujours prêts à rendre compte de votre espérance, avec douceur et respect ; que celui qui aime la vie garde sa langue du mal ; Esther s'approche du roi avec sagesse et douceur.","Si quelqu'un me demandait pourquoi j'espère, que répondrais-je ?"],
[27,11,19,90,60,4,"Ne soyez pas surpris par la fournaise","La fin de toutes choses est proche : soyez sobres, aimez-vous ardemment, servez chacun selon votre don, et ne soyez pas surpris par la fournaise de l'épreuve ; enseigne-nous à compter nos jours ; Daniel annonce des sages éprouvés par le feu pour être purifiés.","Comment vivre l'épreuve sans être surpris ni découragé ?"],
[7,14,19,55,60,5,"Déchargez-vous de vos soucis","Humiliez-vous sous la puissante main de Dieu et déchargez-vous sur lui de tous vos soucis, car il prend soin de vous ; votre adversaire rôde comme un lion : résistez-lui, fermes dans la foi ; remets ton fardeau à l'Éternel ; Samson, rempli de l'Esprit, met en pièces un jeune lion.","Quel souci vais-je remettre à Dieu aujourd'hui ?"],
[24,36,19,119,61,1,"Une lampe dans un lieu obscur","Ajoutez à votre foi la vertu, la connaissance, la maîtrise de soi, la patience, l'amour ; la parole prophétique est comme une lampe qui brille dans un lieu obscur ; ta parole est une lampe à mes pieds ; Jérémie dicte à Baruch les paroles de Dieu, et le rouleau brûlé est réécrit.","Quelle qualité vais-je « ajouter » à ma foi cette semaine ?"],
[4,22,18,18,61,2,"Les faux docteurs","Pierre avertit contre les faux docteurs qui promettent la liberté alors qu'ils sont eux-mêmes esclaves, et rappelle Noé, Lot et Balaam ; Bildad : la lumière du méchant s'éteindra ; Balaam suit l'appât du gain, et son ânesse voit mieux que lui.","Comment discerner un enseignement qui m'éloigne de Dieu ?"],
[26,12,19,90,61,3,"Le Seigneur ne tarde pas","Des moqueurs demandent : où est la promesse de sa venue ? Pour le Seigneur, mille ans sont comme un jour : il ne tarde pas, il est patient, et nous attendons de nouveaux cieux ; mille ans sont à tes yeux comme le jour d'hier ; Ézéchiel : on disait que les visions ne s'accomplissent jamais.","Comment la patience de Dieu me donne-t-elle une chance aujourd'hui ?"],
[3,5,19,32,62,2,"Un avocat auprès du Père","Si quelqu'un a péché, nous avons un avocat auprès du Père, Jésus-Christ le juste ; mais celui qui dit être dans la lumière et hait son frère est encore dans les ténèbres ; heureux celui dont la faute est pardonnée ; la loi demandait d'avouer sa faute et de réparer.","Est-ce que je laisse Jésus plaider pour moi quand je tombe ?"],
[4,32,19,49,62,2,"Le monde passe","N'aimez pas le monde : la convoitise des yeux et l'orgueil de la vie passent, mais celui qui fait la volonté de Dieu demeure pour toujours ; l'homme dans sa gloire ne dure pas ; Ruben et Gad choisissent leurs pâturages avant le pays promis.","Qu'est-ce qui, dans ce monde qui passe, retient trop mon cœur ?"],
[28,1,19,103,62,3,"Enfants de Dieu","Voyez quel amour le Père nous a donné : nous sommes appelés enfants de Dieu, et nous le sommes ; quand il paraîtra, nous lui serons semblables ; comme un père a compassion de ses enfants ; Osée : on les appellera fils du Dieu vivant.","Est-ce que je vis comme un enfant aimé de Dieu ?"],
[9,30,20,14,62,3,"Aimer en actes","N'aimons pas seulement en paroles, mais en actes et en vérité ; et si notre cœur nous condamne, Dieu est plus grand que notre cœur ; celui qui a pitié des malheureux est heureux ; David partage le butin avec ceux qui étaient restés en arrière.","Quel geste d'amour concret puis-je poser aujourd'hui ?"],
[24,28,19,145,62,4,"Dieu est amour","Éprouvez les esprits, car beaucoup de faux prophètes sont venus ; et aimons-nous, car l'amour vient de Dieu : Dieu est amour ; l'Éternel est bon envers tous ; Jérémie fait face au faux prophète Hanania qui annonce une paix mensongère.","Comment discerner ce qui vient vraiment de Dieu ?"],
[36,3,22,2,62,4,"L'amour chasse la crainte","Nous aimons parce qu'il nous a aimés le premier, et l'amour parfait chasse la crainte ; celui qui dit aimer Dieu et hait son frère est un menteur ; sa bannière sur moi, c'est l'amour ; Sophonie : il se réjouira de toi avec des chants, il se taira dans son amour.","Quelle crainte l'amour de Dieu peut-il chasser de mon cœur ?"],
[6,23,19,115,62,5,"Afin que vous sachiez","Ce qui triomphe du monde, c'est notre foi ; Dieu nous a donné la vie éternelle, et cette vie est dans son Fils : je vous écris afin que vous sachiez que vous l'avez ; petits enfants, gardez-vous des idoles ; Josué âgé supplie le peuple de rester attaché à l'Éternel.","Est-ce que je sais que j'ai la vie éternelle ?"],
[11,13,19,86,63,1,"Marcher dans la vérité","L'ancien se réjouit de voir des enfants marcher dans la vérité, et rappelle : aimons-nous, mais ne recevons pas ceux qui déforment la foi ; enseigne-moi tes voies, je marcherai dans ta vérité ; un homme de Dieu se laisse tromper par un vieux prophète qui ment au nom de Dieu.","Comment tenir ensemble l'amour et la vérité ?"],
[10,17,19,101,64,1,"Imiter le bien","Jean félicite Gaïus qui accueille les frères de passage, et reproche à Diotrèphe d'aimer être le premier : n'imite pas le mal, mais le bien ; je marcherai avec un cœur intègre dans ma maison ; Barzillaï et ses amis apportent de quoi manger à David en fuite.","Qui pourrais-je accueillir ou soutenir dans son service ?"],
[7,2,19,83,65,1,"Celui qui peut vous garder","Jude appelle à combattre pour la foi transmise une fois pour toutes, face à ceux qui détournent la grâce : gardez-vous dans l'amour de Dieu ; à celui qui peut vous préserver de toute chute ; le psaume voit les nations comploter contre Dieu ; après Josué, une génération se lève qui ne connaît pas l'Éternel.","Comment me garder dans l'amour de Dieu cette semaine ?"],
[12,23,19,96,52,1,"Une foi qui se voit","Paul rend grâce pour l'œuvre de la foi, le travail de l'amour et la persévérance de l'espérance des Thessaloniciens, qui se sont tournés vers Dieu en quittant les idoles ; racontez sa gloire parmi les nations ; Josias renverse les idoles et revient à Dieu de tout son cœur.","Qu'est-ce qu'on raconte de ma foi autour de moi ?"],
[23,46,19,131,52,2,"Comme une mère, comme un père","Paul rappelle comment il a vécu parmi eux : doux comme une mère qui prend soin de ses enfants, encourageant comme un père, sans chercher la gloire ; mon âme est en moi comme un enfant apaisé près de sa mère ; Ésaïe : je vous porterai jusqu'à votre vieillesse.","Qui Dieu m'a-t-il confié, pour en prendre soin comme un parent ?"],
[9,23,19,125,52,3,"Affermir les frères","Inquiet pour eux, Paul envoie Timothée pour les affermir, et se réjouit de leur fidélité : que le Seigneur fasse croître votre amour les uns pour les autres ; ceux qui se confient en l'Éternel sont inébranlables ; Jonathan vient fortifier la confiance de David en Dieu.","Qui puis-je fortifier dans sa foi cette semaine ?"],
[3,18,20,6,52,4,"Une vie sainte et paisible","La volonté de Dieu, c'est votre sanctification : vivez dans la pureté, aimez-vous, menez une vie tranquille et travaillez de vos mains ; va vers la fourmi, paresseux ; la loi demandait de ne pas imiter les mœurs des peuples voisins.","Quel aspect concret de ma vie Dieu veut-il sanctifier ?"],
[1,25,19,23,52,4,"Toujours avec le Seigneur","Pour ceux qui sont morts, ne soyez pas tristes comme ceux qui n'ont pas d'espérance : le Seigneur descendra, les morts en Christ ressusciteront, et nous serons toujours avec lui ; j'habiterai dans la maison de l'Éternel pour toujours ; Abraham meurt rassasié de jours et rejoint les siens.","Pour qui ai-je besoin de vivre le deuil avec espérance ?"],
[36,1,19,121,52,5,"Enfants de la lumière","Le jour du Seigneur viendra comme un voleur dans la nuit, mais vous êtes enfants de la lumière : veillons, revêtus de la foi, de l'amour et de l'espérance ; celui qui te garde ne sommeille pas ; Sophonie annonce le jour de l'Éternel et appelle à le chercher.","Est-ce que je vis éveillé ou endormi dans ma foi ?"],
[16,12,19,34,52,5,"Toujours joyeux","Soyez toujours joyeux, priez sans cesse, rendez grâce en toute circonstance : c'est la volonté de Dieu ; n'éteignez pas l'Esprit, examinez tout, retenez ce qui est bon ; je bénirai l'Éternel en tout temps ; à la dédicace des murailles, la joie de Jérusalem s'entendait de loin.","Pour quoi puis-je rendre grâce, même aujourd'hui ?"],
[23,63,19,137,53,1,"Dieu rendra justice","Paul encourage des croyants persécutés : Dieu est juste, il rendra justice et vous donnera le repos quand le Seigneur Jésus paraîtra ; au bord des fleuves de Babylone, les exilés pleurent et crient leur soif de justice ; Ésaïe : dans toutes leurs détresses, il a été en détresse.","Quelle injustice ai-je besoin de remettre à Dieu ?"],
[27,8,19,37,53,2,"Ne vous laissez pas ébranler","Ne vous laissez pas troubler par ceux qui disent que le jour du Seigneur est déjà là : l'homme du péché s'élèvera, mais le Seigneur le détruira par le souffle de sa bouche ; ne t'irrite pas contre les méchants, ils passeront comme l'herbe ; Daniel voit une petite corne s'élever contre Dieu, puis être brisée sans main d'homme.","Qu'est-ce qui m'inquiète dans l'avenir, que je peux confier à Dieu ?"],
[11,2,19,112,53,2,"Tenez ferme","Dieu vous a choisis pour être sauvés : tenez ferme et retenez ce que vous avez appris, et que Dieu console et affermisse vos cœurs ; son cœur est ferme, confiant en l'Éternel ; David mourant dit à Salomon : fortifie-toi et garde les commandements.","Quelle vérité de la foi dois-je retenir fermement aujourd'hui ?"],
[16,6,20,24,53,3,"Ne vous lassez pas","Paul demande qu'on prie pour lui : le Seigneur est fidèle, il vous affermira ; travaillez paisiblement pour gagner votre pain, et ne vous lassez pas de faire le bien ; j'ai vu le champ du paresseux envahi par les ronces ; Néhémie : je fais un grand ouvrage, je ne peux pas descendre.","Dans quel bien ai-je besoin de persévérer ?"],
[26,1,19,97,66,1,"Celui qui vient","Jean, exilé à Patmos, reçoit la révélation de Jésus-Christ : voici, il vient avec les nuées, et tout œil le verra ; je suis l'Alpha et l'Oméga ; nuées et obscurité l'environnent ; Ézéchiel, exilé lui aussi, voit la gloire de Dieu au bord du fleuve.","Qu'est-ce que ça change de savoir que Jésus est le commencement et la fin ?"],
[27,10,19,118,66,1,"Ne crains pas, je suis le vivant","Jean voit le Fils de l'homme, les yeux comme une flamme, et tombe à ses pieds ; Jésus pose sa main sur lui : ne crains pas, je suis le premier et le dernier, le vivant, je tiens les clés de la mort ; je ne mourrai pas, je vivrai ; Daniel tombe devant la vision, et une main le relève : ne crains rien.","Quelle peur a besoin de la main de Jésus posée sur moi ?"],
[11,14,19,63,66,2,"Le premier amour","Jésus écrit aux Églises : à Éphèse, tu as abandonné ton premier amour, souviens-toi et reviens ; à Smyrne, sois fidèle jusqu'à la mort ; mon âme a soif de toi dès l'aurore ; Roboam remplace les boucliers d'or par des boucliers de bronze.","Mon amour pour Jésus a-t-il perdu de son éclat ?"],
[28,7,22,5,66,3,"Je me tiens à la porte","À Laodicée, ni froide ni bouillante, Jésus dit : je me tiens à la porte et je frappe, si quelqu'un ouvre, j'entrerai et je mangerai avec lui ; dans le Cantique, le bien-aimé frappe : ouvre-moi ; Osée compare son peuple à un gâteau cuit d'un seul côté.","À quelle porte de ma vie Jésus frappe-t-il aujourd'hui ?"],
[11,22,19,99,66,4,"Saint, saint, saint","Une porte s'ouvre dans le ciel : autour du trône, les êtres vivants chantent saint, saint, saint, et les anciens jettent leurs couronnes ; il est saint, l'Éternel notre Dieu ; le prophète Michée voyait l'Éternel assis sur son trône, entouré de l'armée du ciel.","Qu'est-ce que je pourrais « déposer » devant le trône de Dieu ?"],
[1,49,19,98,66,5,"L'Agneau digne d'ouvrir le livre","Personne ne peut ouvrir le livre, et Jean pleure ; mais le Lion de Juda a vaincu, et c'est un Agneau immolé qui le prend ; chantez à l'Éternel un cantique nouveau ; Jacob annonçait : le sceptre ne s'écartera pas de Juda.","Est-ce que je crois que Jésus tient l'histoire entre ses mains ?"],
[2,29,19,96,66,5,"Toute créature loue l'Agneau","Des milliers d'anges et toutes les créatures chantent : l'Agneau immolé est digne de recevoir la puissance, la gloire et la louange, il nous a rachetés de toute tribu et de toute langue ; chantez à l'Éternel, toute la terre ; au tabernacle, un agneau était offert chaque matin et chaque soir.","Pour quoi vais-je louer l'Agneau aujourd'hui ?"],
[38,1,19,13,66,6,"Jusqu'à quand, Seigneur ?","Les sceaux s'ouvrent : guerre, famine, mort, et les martyrs crient sous l'autel : jusqu'à quand, Seigneur ? ; le psalmiste demandait : jusqu'à quand m'oublieras-tu ? ; Zacharie voit des cavaliers, et l'ange demande : jusqu'à quand n'auras-tu pas pitié ?","Quelle question « jusqu'à quand ? » puis-je déposer devant Dieu ?"],
[26,9,19,91,66,7,"Marqués du sceau de Dieu","Avant le jugement, un ange marque du sceau de Dieu le front de ses serviteurs ; celui qui demeure sous l'abri du Très-Haut repose à l'ombre du Tout-Puissant ; Ézéchiel voit marquer ceux qui gémissent sur le mal.","Est-ce que je sais que j'appartiens à Dieu, marqué de son sceau ?"],
[23,4,19,23,66,7,"Une foule innombrable","Une foule immense de toutes les nations, vêtue de blanc, palmes à la main, loue Dieu ; l'Agneau sera leur berger, il les conduira aux sources d'eau vive, et Dieu essuiera toute larme ; l'Éternel est mon berger, il me conduit près des eaux paisibles ; Ésaïe : il y aura un abri contre la chaleur.","Quelle larme ai-je besoin que Dieu essuie ?"],
[2,9,19,141,66,8,"L'encens des prières","Un silence se fait dans le ciel, puis l'encens monte avec les prières des saints, et les trompettes annoncent les jugements ; que ma prière soit devant toi comme l'encens ; en Égypte, la grêle et le feu tombaient comme un avertissement.","Est-ce que je crois que mes prières montent jusqu'à Dieu ?"],
[29,1,19,81,66,9,"Ils ne changèrent pas","Les sauterelles et les fléaux frappent, mais les survivants ne renoncent ni à leurs idoles ni à leurs crimes ; si mon peuple m'écoutait ! ; Joël décrit l'invasion des sauterelles et appelle à revenir à Dieu.","Qu'est-ce qui m'empêche de changer, même quand Dieu m'avertit ?"],
[24,15,19,119,66,10,"Le petit livre","Un ange donne à Jean un petit livre à manger : doux comme le miel dans la bouche, amer dans les entrailles, et il doit encore prophétiser ; que tes paroles sont douces à mon palais ; Jérémie : j'ai dévoré tes paroles, elles ont fait la joie de mon cœur.","Quelle parole de Dieu m'est douce, et laquelle m'est amère ?"],
[38,4,19,2,66,11,"Les deux témoins","Deux témoins prophétisent, sont tués, puis Dieu les relève ; la septième trompette sonne : le royaume du monde est remis à notre Seigneur ; les nations s'agitent en vain ; Zacharie voit les deux oliviers : ni par la puissance, ni par la force, mais par mon Esprit.","Comment être un témoin fidèle, même quand cela coûte ?"],
[2,1,18,40,66,12,"La femme et le dragon","Une femme enfante un fils qui doit gouverner les nations, un dragon veut le dévorer, mais l'enfant est enlevé vers Dieu et la femme est nourrie au désert ; Dieu montre à Job le Béhémoth, qu'il a créé et qu'il domine ; Pharaon voulait faire mourir les enfants d'Israël.","Est-ce que je crois que Dieu protège ce qu'il a promis ?"],
[7,5,19,144,66,12,"Vaincu par le sang de l'Agneau","Un combat éclate dans le ciel, et l'accusateur de nos frères est précipité : ils l'ont vaincu par le sang de l'Agneau et par la parole de leur témoignage ; béni soit l'Éternel qui exerce mes mains au combat ; dans le cantique de Débora, même les étoiles combattaient.","Quel témoignage puis-je opposer à l'accusateur ?"],
[27,5,19,73,66,13,"La persévérance des saints","Une bête reçoit le pouvoir de séduire et réclame l'adoration de toute la terre : c'est ici la persévérance et la foi des saints ; le psalmiste envie les puissants jusqu'à ce qu'il comprenne leur fin ; Belschatsar défie Dieu, et une main écrit sa chute sur le mur.","Quelle pression me pousse à « adorer » autre chose que Dieu ?"],
[29,3,19,126,66,14,"Heureux ceux qui meurent dans le Seigneur","L'Agneau se tient sur le mont Sion, un ange proclame l'Évangile éternel, une voix dit : heureux ceux qui meurent dans le Seigneur, puis vient la moisson de la terre ; ceux qui sèment avec larmes moissonnent avec joie ; Joël : lancez la faucille, car la moisson est mûre.","Est-ce que je vis en pensant à la moisson finale ?"],
[5,32,19,86,66,15,"Le cantique de Moïse et de l'Agneau","Au bord d'une mer de verre, les vainqueurs chantent le cantique de Moïse et de l'Agneau : grandes et admirables sont tes œuvres, toutes les nations viendront t'adorer ; toutes les nations viendront se prosterner devant toi ; Moïse chante le Rocher dont l'œuvre est parfaite.","Quelle œuvre de Dieu me fait chanter aujourd'hui ?"],
[2,10,19,119,66,16,"Tu es juste","Les coupes sont versées, et l'ange proclame : tu es juste, toi qui es et qui étais ; mais beaucoup accusent Dieu au lieu de changer ; tu es juste, Éternel, et tes jugements sont droits ; en Égypte, les ténèbres couvrent le pays, mais Pharaon s'endurcit.","Est-ce que je fais confiance à la justice de Dieu ?"],
[26,23,20,7,66,17,"L'Agneau vaincra","La grande prostituée, ivre de puissance et de richesse, séduit les rois de la terre, mais l'Agneau vaincra, car il est Seigneur des seigneurs et Roi des rois ; les Proverbes décrivent la séductrice qui entraîne à la mort ; Ézéchiel dénonce un peuple infidèle qui court après les puissants.","Quelle séduction du monde m'attire le plus ?"],
[24,51,19,49,66,18,"Babylone est tombée","Babylone la grande tombe en une heure, les marchands pleurent leurs richesses, et une voix crie : sortez du milieu d'elle, mon peuple ; l'homme dans sa gloire ne dure pas ; Jérémie : sortez du milieu de Babylone, que chacun sauve sa vie.","De quelle « Babylone » Dieu m'appelle-t-il à sortir ?"],
[17,2,19,45,66,19,"Les noces de l'Agneau","Une foule immense crie : alléluia, le Seigneur règne ! Les noces de l'Agneau sont venues, et son épouse s'est préparée ; heureux ceux qui sont invités ; le psaume chante les noces du roi ; Esther est choisie et couronnée, et le roi donne un grand festin.","Comment je me prépare à la rencontre avec Jésus ?"],
[6,5,19,2,66,19,"Fidèle et Véritable","Le ciel s'ouvre : un cavalier sur un cheval blanc s'appelle Fidèle et Véritable, la Parole de Dieu, Roi des rois et Seigneur des seigneurs ; le Fils régnera sur les nations ; Josué rencontre le chef de l'armée de l'Éternel et ôte ses sandales.","Est-ce que je laisse Jésus mener mes combats ?"],
[26,38,19,9,66,20,"Le jugement dernier","Satan est lié puis vaincu pour toujours, et tous comparaissent devant le grand trône blanc : les livres sont ouverts, et le livre de vie ; l'Éternel siège pour juger le monde avec justice ; Ézéchiel voyait Gog se lever contre le peuple de Dieu et être vaincu.","Est-ce que mon nom est écrit dans le livre de vie, et est-ce que j'en vis ?"],
[26,48,19,46,66,21,"Toutes choses nouvelles","Je vis un ciel nouveau et une terre nouvelle : voici la demeure de Dieu avec les hommes, il essuiera toute larme, et celui qui siège sur le trône dit : voici, je fais toutes choses nouvelles ; Dieu est au milieu d'elle, elle ne chancelle pas ; Ézéchiel donne son nom à la ville : l'Éternel est ici.","Quelle larme ai-je hâte que Dieu essuie pour toujours ?"],
[26,40,19,48,66,21,"La ville sainte","La nouvelle Jérusalem descend du ciel, brillante comme une pierre précieuse ; elle n'a pas de temple, car le Seigneur et l'Agneau en sont le temple, ni de soleil, car la gloire de Dieu l'éclaire ; grand est l'Éternel dans la ville de notre Dieu ; Ézéchiel voit un homme mesurer la ville et le temple à venir.","Est-ce que je me réjouis à l'avance de vivre dans la présence de Dieu ?"],
[23,12,19,36,66,22,"Le fleuve de vie","Un fleuve d'eau vive coule du trône de Dieu et de l'Agneau, l'arbre de vie porte son fruit chaque mois, ses feuilles guérissent les nations, et ils verront sa face ; auprès de toi est la source de la vie ; Ésaïe : vous puiserez avec joie aux sources du salut.","Est-ce que je vis déjà de la source de vie ?"],
[39,4,19,150,66,22,"Viens, Seigneur Jésus !","Voici, je viens bientôt : je suis l'Alpha et l'Oméga, l'étoile brillante du matin ; l'Esprit et l'épouse disent : viens ! que celui qui a soif vienne ; amen, viens, Seigneur Jésus ; que tout ce qui respire loue l'Éternel ; Malachie : pour vous qui craignez mon nom se lèvera le soleil de justice.","Au bout de cette année avec la Parole, qu'est-ce que Dieu a changé en moi ?"]];
